-- 나는 반딧불 챌린지 (ykday4fp / 나는-반딧불-챌린지)
update public.memes set
  description = '''나는 반딧불''은 밴드 중식이가 2020년 발표한 곡을 가수 황가람이 리메이크해 2024년 10월 발매한 노래다. 황가람 버전은 멜론 일간차트에서 2024년 12월 12일 자 최고 4위에 올랐고 이후 한 달 넘게 톱5를 지켰다는 보도가 있다. 2024년 12월 보도에 따르면 초등학생 네 명이 기타 한 대와 전자피아노에 맞춰 부른 1분짜리 커버 영상은 SNS에서 한 달 만에 합계 조회수 1,000만 회를 넘겼다. 보도는 챌린지 형식보다 노래와 어린이 커버 영상이 함께 화제가 된 흐름으로 전한다.',
  origin = '2020년 밴드 중식이가 발표한 동명의 원곡이 있고, 황가람의 리메이크 곡은 2024년 10월 발매됐다. 초등학생 커버 영상은 아이들에게 노래를 가르치는 몬스터팩토리키즈 대표가 기획해 올린 것으로 2024년 12월 서울신문이 보도했다.',
  usage_note = '어린 학생들의 커버가 화제가 된 노래나 발라드 리메이크가 뒤늦게 인기를 얻은 사례를 이야기할 때 쓰인다. 노래 추천 대화에서 원곡과 리메이크를 함께 언급하며 가볍게 인용하기 좋다.',
  caution = '원곡 밴드 중식이와 리메이크 가수 황가람의 기여를 구분해 표기하는 것이 좋다. 어린이 출연 영상은 얼굴과 신상이 드러나지 않도록 주의하고, 영상이나 음원을 재업로드할 때는 저작권자와 기획사의 허락 여부를 확인해야 한다.',
  usage_examples = '[{"situation":"노래 추천 대화","text":"이 노래 원곡 밴드 따로 있는 거 알아? 초등학생 커버도 유명하더라"},{"situation":"댓글","text":"애들 목소리로 들으니까 가사가 더 찡하다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ykday4fp'
  and slug = '나는-반딧불-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

