-- 1577-1577 대리운전 CM송 (upktm4ve / 1577-1577-대리운전-CM송)
update public.memes set
  description = '''앞뒤가 똑같은 전화번호''로 알려진 1577-1577은 대리운전 업체의 전화번호로, 이 번호 자체를 가사로 만든 CM송이 널리 알려졌다. 가사는 ''앞뒤가 똑같은 전화번호 1577'', ''앞뒤가 똑같은 번호 대리운전''을 반복하는 단순한 구조다. 2012년에는 이수근이 모델로 나서 이 노래를 부르며 홍보했고, 2018년 5월 보도 기준으로는 신동엽을 모델로 한 새 CM송이 나와 있었다. 2018년에는 이 노래가 노래방 6월 신곡 목록에 오른 장면이 온라인에서 화제가 되었다. 2021년 8월에는 카카오모빌리티 자회사가 이 서비스 운영사와 신규법인을 세우자 대리운전 업계가 반발했다는 보도가 나왔다.',
  origin = '2012년 배우 이수근이 모델로 나서 CM송을 부르는 형태로 홍보한 대리운전 광고로 보도됐다. 2021년 8월에는 카카오모빌리티 자회사 CMNP가 1577 대리운전 운영사 코리아드라이브와 신규법인 ''케이드라이브''를 세워 서비스를 이관받았고 대리운전 업계가 반발했다고 뉴스핌이 전했다.',
  usage_note = '회문처럼 읽히는 전화번호를 가리키거나, 번호를 노래로 외우게 하는 CM송 마케팅을 설명할 때 예로 쓴다. 광고 노래가 오랫동안 기억에 남은 사례로 가볍게 인용하기 좋다.',
  caution = '광고 CM송은 광고주와 제작사에 저작권이 있으므로 음원이나 영상을 무단 재업로드하지 않는다. 음주운전과 관련된 대리운전 맥락으로 농담을 엮는 것은 민감할 수 있어 피한다. 업체 소유와 모델 정보는 시기에 따라 바뀌었으므로 현재 상태로 단정하지 않는다.',
  usage_examples = '[{"situation":"카톡","text":"앞뒤가 똑같은 전화번호 1577 이거 노래 아직도 생각남ㅋㅋ"},{"situation":"댓글","text":"CM송 한 번 들으면 번호가 안 잊혀짐"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'upktm4ve'
  and slug = '1577-1577-대리운전-CM송'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

