-- STAYC ASAP 챌린지 (fnk7kztn / STAYC-ASAP-챌린지)
update public.memes set
  description = '''ASAP''은 걸그룹 스테이씨가 2021년 4월 8일 두 번째 싱글 앨범 ''STAYDOM''의 타이틀곡으로 공개한 버블검 팝 곡이다. 소속사는 뮤직비디오가 공개 약 사흘 만에 1,000만 뷰를 넘었다고 발표했다. 가온 디지털 차트에는 2021년 4월 11~17일 자 108위로 진입했고 6월 6~12일 자에서 9위까지 올랐다. 발매 이틀 전인 4월 6일에는 안무 일부를 보여주는 티저 영상이 공개됐고, 국내 보도는 이를 ''꾹꾹이춤''으로 소개했다. 틱톡 등에서의 챌린지 확산은 두 자료에서 다루지 않는다.',
  origin = '2021년 4월 8일 발매된 두 번째 싱글 앨범 ''STAYDOM''의 타이틀곡이다. 가온 디지털 차트 데뷔 주차는 2021년 4월 11~17일 자이며, 블랙아이드필승과 전군이 작곡하고 라도가 편곡했다.',
  usage_note = '신인 걸그룹의 곡이 짧은 안무 영상과 함께 알려진 사례를 이야기할 때 인용한다. 2021년 신인 그룹의 음원 성장 흐름을 설명할 때 예로 들기 좋다.',
  caution = '뮤직비디오와 안무 영상은 소속사와 제작사의 저작권이 있으므로 무단 재업로드를 피한다. 챌린지 참여 영상에는 멤버 외 일반인 얼굴이나 개인 정보가 나올 수 있으므로 노출을 주의한다. 뷰 수와 차트 기록은 집계 시점 기준이므로 현재 기록으로 단정하지 않는다.',
  usage_examples = '[{"situation":"음악 얘기","text":"ASAP 꾹꾹이춤 아직도 귀에 맴돈다"},{"situation":"댓글","text":"ASAP 뮤비 사흘 만에 1000만 뷰 찍었던 게 벌써 몇 년 전이라니"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'fnk7kztn'
  and slug = 'STAYC-ASAP-챌린지'
