-- 나야 나(PICK ME) 신드롬 (gqv25muj / 나야-나(PICK-ME)-신드롬)
update public.memes set
  description = '''나야 나(PICK ME)''는 Mnet ''프로듀스 101 시즌2''의 테마곡으로 2017년 4월 발표된 곡이다. 프로그램은 2017년 4월 7일 첫 방송을 시작해 6월 16일 최종 생방송으로 마무리됐고, 방송 중 굿데이터코퍼레이션 TV화제성 비드라마 부문 9주 연속 1위를 기록했다. 2017년 6월 보도에 따르면 ''나야 나'' 음원은 발표 두 달 뒤에도 차트 50위권대를 지켰다. 당시 여러 예능 프로그램에서 방송인들이 ''나야 나''를 패러디한 노래를 불렀다는 회고 보도가 있으며, 이 프로그램을 통해 보이그룹 워너원의 데뷔가 확정됐다.',
  origin = '2017년 4월 7일부터 6월 16일까지 방송된 Mnet ''프로듀스 101 시즌2''의 테마곡이다. 4월 발표된 이 곡은 방송 기간 내내 프로그램의 대표곡으로 언급됐고 6월에도 차트 50위권대에 머물렀다.',
  usage_note = '오디션 프로그램의 인기 열풍이나 연습생 군무 패러디를 이야기할 때 쓰인다. 방송 소재를 언급하며 ''나야 나''의 한 장면을 가볍게 인용하는 맥락에서 활용된다.',
  caution = '오디션 출연자 개인의 사생활이나 투표 결과를 두고 특정 연습생을 조롱하는 식으로 쓰지 않도록 한다. 방송 영상과 안무 클립은 Mnet과 제작진의 저작권을 확인해야 한다. 노랫말 전체를 인용하지 않는다.',
  usage_examples = '[{"situation":"예능 얘기","text":"나야 나 군무 패러디 아직도 못 잊음ㅋㅋ"},{"situation":"댓글","text":"오디션 신드롬은 픽미 때가 제일 셌다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'gqv25muj'
  and slug = '나야-나(PICK-ME)-신드롬'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

