-- 리사 다리 밈 챌린지 (n2k442e4 / 리사-다리-밈-챌린지)
update public.memes set
  description = '''Did it work?'' 밈은 블랙핑크 리사의 댄스 퍼포먼스 영상 ''LILI''s FILM #3''의 다리 장면에 다른 사물이나 이미지를 합성하고 이 문구를 붙이는 놀이다. 2020년 4월 말부터 SNS에서 퍼지기 시작했고, 돌리 파튼이 직접 게시물을 올리면서 해외로 더 널리 확산됐다. 리사는 빌보드 인터뷰에서 팬들의 창작에 고마움을 표했다. 합성 대상과 방식이 다양해 이미지 합성 놀이 형태로 이어졌다. 캐피탈FM은 당시 이 밈이 소셜미디어에서 큰 유행이 됐다고 전했다.',
  origin = '블랙핑크 리사의 ''LILI''s FILM #3'' 댄스 퍼포먼스 영상 속 다리 장면이 원본이다. 이 장면을 활용한 합성물이 2020년 4월 말 트위터에서 퍼졌고, 2020년 4월 29일 돌리 파튼이 ''Did it work?'' 게시물을 올리는 등 해외 유명인도 참여했다.',
  usage_note = '사진이나 영상 속 다리를 사물과 합성해 웃음을 주는 놀이를 이야기할 때 쓰인다. 장난스러운 합성 이미지에 ''Did it work?'' 문구를 붙여 응답하는 식으로 활용된다.',
  caution = '특정 연예인의 신체 일부를 소재로 한 합성물은 성적 대상화나 외모 비하로 흐를 수 있으므로 피한다. 원본 영상과 캡처는 소속사와 제작사의 저작권을 확인해야 한다. 합성 이미지를 실제 인물 사진에 적용해 조롱하는 용도로 쓰지 않는다.',
  usage_examples = '[{"situation":"카톡","text":"이 사진에 Did it work? 붙여서 보내봤다ㅋㅋ"},{"situation":"댓글","text":"리사 다리 밈 아직도 살아 있네"}]'::jsonb,
  origin_year = 2020,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'n2k442e4'
  and slug = '리사-다리-밈-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

