-- 무한도전 강변북로가요제 (df42f2ya / 무한도전-강변북로가요제)
update public.memes set
  description = '강변북로가요제는 2007년 7월 7일과 14일 두 차례 MBC 무한도전에서 방송된 음악 특집이다. 출연진이 각자 준비한 곡으로 시상식 형식의 무대를 펼쳤고, 방송을 위해 만든 곡들이 인기를 얻으면서 같은 해 9월 4일 서울음반을 통해 음반이 나왔다. 2013년 보도는 이 편이 2년마다 열리는 무한도전 가요제의 출발점이라고 소개했다. 2009년에는 올림픽대로 듀엣가요제 편이 방송됐고, 2015년 6월 보도는 제작진이 그해에도 가요제를 준비 중이라고 전했다.',
  origin = '2007년 MBC 무한도전의 ''강변북로가요제'' 편으로 방송됐다. 7월 7일과 14일 두 차례 방영됐고 음반 프로듀서는 안정훈과 윤일상으로 표기돼 있다. 음반은 같은 해 9월 4일 서울음반에서 발매됐으며, 2013년과 2015년 보도는 이 편을 무한도전 가요제 시리즈의 시작으로 기술한다.',
  usage_note = '무한도전 음악 특집이나 연예인 합동 가요제 같은 기획을 언급할 때 쓴다. 여러 사람이 각자 무대를 맡는 콜라보 프로젝트를 이야기할 때 ''강변북로가요제급''이라는 식으로 비유할 수 있다. 특정 회차를 가리킬 때는 2009년 올림픽대로 듀엣가요제 등 다른 편과 구분하도록 연도를 함께 적는 편이 정확하다.',
  caution = '방송 클립이나 수록곡 음원을 그대로 가져오면 방송사와 가수의 저작권이 걸린다. 출연 가수의 무대 장면을 캡처해 쓸 때는 출처와 권리 관계를 확인해야 한다. 가요제 회차가 여러 개라 ''무한도전 가요제''로 뭉뚱그리면 편명이 틀릴 수 있으니 편명과 연도를 함께 쓴다.',
  usage_examples = '[{"situation":"카톡","text":"이번 콜라보 기획 진짜 강변북로가요제 느낌이다ㅋㅋ"},{"situation":"SNS 댓글","text":"무한도전 가요제 시작이 2007년 강변북로였지, 그때 무대 다 기억난다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'df42f2ya'
  and slug = '무한도전-강변북로가요제'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

