-- 제로슈거 열풍 (fedrc4zu / 제로슈거-열풍)
update public.memes set
  description = '제로슈거 열풍은 설탕 대신 대체 감미료를 넣은 음료와 주류가 건강과 맛을 함께 챙기는 ''헬시플레저'' 흐름을 타고 확산된 현상을 가리킨다. 롯데칠성음료가 2022년 9월 중순 내놓은 소주 ''처음처럼 새로''가 대표 사례로, 과당을 빼고 칼로리를 낮춘 제품이었다. 출시 7개월 만에 누적 판매 1억 병을 넘었다는 보도가 나오자 하이트진로도 진로 제품을 제로슈거로 내놓는 등 경쟁 제품이 잇따랐다. 제품 이름과 표시 문구가 소비자에게 헷갈린다는 지적도 함께 제기됐다.',
  origin = '2022년 9월 중순 롯데칠성음료가 과당 대신 대체 감미료를 쓴 ''처음처럼 새로''를 출시하면서 제로슈거 소주가 크게 주목받았다. 2023년 1월 보도에 따르면 무가당 소주는 무학과 대선주조가 먼저 내놓았고, 2022년 제로탄산 시장도 3000억원을 넘어선 것으로 추정됐다. 2023년 5월 보도에서 ''새로''는 출시 7개월 만에 누적 판매 1억 병을 기록했다.',
  usage_note = '건강을 챙기면서도 맛을 포기하지 않으려는 소비 흐름을 이야기할 때 쓴다. 칼로리가 걱정되는 술자리에서 제로 소주 얘기를 꺼내거나, 헬시플레저 트렌드를 설명할 때 자연스럽게 인용할 수 있다. 제로 제품을 말할 때는 당류가 0이라는 뜻인지 칼로리가 낮다는 뜻인지 구분해 쓰면 오해를 줄일 수 있다.',
  caution = '제로슈거라는 표시는 당류 함량을 정확히 뜻하지 않을 수 있어, 라벨이나 제품명만 보고 당류 함량을 단정하지 않는 편이 안전하다. 특정 회사 제품을 과장 광고라고 단정하는 표현은 사실 확인 없이 쓰지 않는다. 칼로리와 판매량 수치는 보도 시점에 따라 달라지므로 인용할 때 출처와 시점을 함께 적는다.',
  usage_examples = '[{"situation":"카톡","text":"제로슈거 소주라고 칼로리까지 제로는 아니더라ㅋㅋ 헬시플레저도 라벨 확인이 먼저임"},{"situation":"SNS 댓글","text":"제로슈거 소주 열풍 보면 건강 챙기면서 즐기는 게 트렌드인 듯"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'fedrc4zu'
  and slug = '제로슈거-열풍'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

