-- SSG 쓱 (5mg8twnt / SSG-쓱)
update public.memes set
  description = 'SSG 쓱은 신세계 SSG닷컴이 2015년 12월 31일 공개한 TV 광고에서 시작된 말이다. 배우 공유와 공효진이 커플로 출연해 브랜드명 SSG를 한글 ''쓱''으로 발음하는 장면이 중독성 있다는 반응을 얻었다. 광고는 백화점에서 이마트까지 한 번에 쇼핑할 수 있다는 SSG닷컴의 강점을 ''쓱''이라는 발음으로 표현했다. 짧은 한 글자 대사가 화제가 되며 광고 반응이 뜨거웠다는 보도가 이어졌다. 광고 이후 두 사람의 TV 광고는 시리즈로 공개될 예정이라고 전해졌다.',
  origin = '2015년 12월 31일부터 공개된 신세계 SSG닷컴의 새 TV CF로, 공유와 공효진이 광고 모델로 발탁돼 커플로 출연했다. 2016년 1월 보도에 따르면 SSG닷컴 통합 런칭 2주년을 맞은 캠페인이었고, 두 사람의 TV 광고는 이후 시리즈로 공개될 예정이었다.',
  usage_note = '짧은 한 글자 대답으로 상대의 말을 받아칠 때나 브랜드 이름을 재미있게 발음해 말할 때 쓴다. 간단히 답하거나 무심하게 넘길 때 ''쓱''이라고 응답하는 식으로 패러디한다. 광고 대사에서 나온 말이라 상품 추천 맥락에서 쓰면 광고 메시지처럼 읽힐 수 있다는 점을 고려한다.',
  caution = '광고 영상이나 장면 캡처를 그대로 퍼 나르면 광고주와 제작사의 저작권 문제가 생길 수 있다. 공유와 공효진은 광고에 출연한 배우이므로 언급할 때는 광고 출연 사실에 한정하고, 사생활을 추측하거나 조롱하는 식으로 엮지 않는다. 광고 성과 수치는 보도 시점에 따라 달라지므로 인용할 때 출처와 날짜를 함께 밝힌다.',
  usage_examples = '[{"situation":"카톡","text":"오늘 저녁 메뉴 뭐가 좋아? 쓱ㅋㅋ"},{"situation":"SNS 댓글","text":"이 짤 보니까 SSG 쓱 광고 생각난다ㅋㅋ 발음 중독성 미쳤음"}]'::jsonb,
  origin_year = 2015,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '5mg8twnt'
  and slug = 'SSG-쓱'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

