-- 김예지 사격 짤 (6tcztjdp / 김예지-사격-짤)
update public.memes set
  description = '김예지는 사격 선수로, 2024년 파리올림픽 여자 10m 공기권총에서 은메달을 땄다. 대회 기간 온라인에서는 무표정하게 점수를 확인하는 침착한 모습이 화제가 됐고, 누리꾼들은 그의 사격 자세를 본뜬 사진과 영상을 올렸다. 화제의 영상은 2024년 5월 아제르바이잔 바쿠 국제사격연맹 월드컵 25m 권총 경기 장면이다. 2024년 8월 1일 보도에 따르면 BBC는 SNS에 그의 사진을 올리며 올림픽에서 가장 쿨한 운동선수라고 소개했다. 8월 2일 25m 권총 본선에서는 급사 중 시간을 초과해 0점을 쏴 27위에 그쳤다.',
  origin = '2024년 파리올림픽 기간 김예지 선수의 사격 장면이 온라인에서 확산되며 생긴 밈이다. 누리꾼이 주목한 영상은 2024년 5월 바쿠 월드컵 25m 권총 경기의 마지막 한 발 장면이며, 2024년 8월 1일 보도에서 외신의 호평과 함께 소개됐다.',
  usage_note = '경기 결과에 크게 흔들리지 않고 담담하게 자기 할 일을 한 사람을 표현할 때 쓴다. 주변이 당황해도 혼자 침착한 상황을 설명할 때 가볍게 인용할 수 있다. 짤을 쓸 때는 선수의 실제 경기 맥락을 살려 칭찬이나 공감의 의미로 쓰는 것이 자연스럽다.',
  caution = '실존 선수의 얼굴과 사진을 합성하거나 과장된 패러디에 쓰면 초상권과 선수 명예를 침해할 수 있다. 25m 권총 0점 탈락처럼 경기 실수를 놀리는 용도로 쓰지 않는다. 중계 방송 화면 캡처는 방송사 저작물이므로 개인 게시물에 재사용하지 않는 편이 안전하다. 외모나 표정을 비하하는 방향으로 쓰지 않는다.',
  usage_examples = '[{"situation":"카톡","text":"팀플 발표 망해도 김예지처럼 무표정 유지하는 중ㅋㅋ"},{"situation":"SNS 댓글","text":"이 사진 보니까 파리올림픽 김예지 쿨함이 다시 생각난다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '6tcztjdp'
  and slug = '김예지-사격-짤'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

