-- 왼손은 거들 뿐 (e4esmtr7 / 왼손은-거들-뿐)
update public.memes set
  description = '''왼손은 거들 뿐''은 일본 만화 『슬램덩크』의 명대사로 알려져 있다. 작품은 일본에서 1990~1996년 주간 소년점프에 연재됐고, 한국에서는 1992~1996년 소년챔프 별책부록에 실린 뒤 1998~1999년 SBS에서 만화영화로 방송됐다. 2012년 3월 KBS ''1대 100''에서 농구선수 출신 해설가 우지원이 이 대사가 나오는 애니메이션을 묻는 문제에 답을 알지 못해 찬스를 쓰면서 화제가 되기도 했다. 이 일화는 농구 인기 선수도 모를 수 있는 명대사로 회자된 사례다.',
  origin = '일본 만화 『슬램덩크』에 나오는 대사로, 원작은 1990년부터 1996년까지 일본 주간 소년점프에 연재됐다. 한국에서는 1992년부터 1996년까지 소년챔프 별책부록에 실렸고 1998년부터 1999년까지 SBS에서 만화영화로 방송됐다.',
  usage_note = '농구 경기의 결정적인 장면을 두고 농담처럼 인용하거나, 자기 역할을 낮춰 말할 때 쓸 수 있다. 팀 프로젝트에서 자기 몫이 작았다고 말하거나, 친구가 결정타를 날렸을 때 ''나는 왼손은 거들 뿐''이라고 받아치는 식이다. 원작 장면을 떠올리게 하는 말이므로 농구 이야기가 아닌 자리에서도 가볍게 쓸 수 있다.',
  caution = '『슬램덩크』 캐릭터 이미지와 명장면 캡처는 원작사와 방송사의 저작물이라 게시물에 그대로 옮기지 않는 편이 안전하다. 방송 퀴즈에서 출연자가 답을 몰랐던 사례처럼 특정인을 놀리는 맥락으로 쓰지 않는다. 대사의 뜻은 사람마다 해석이 나뉠 수 있으므로 정답이 정해진 것처럼 설명하지 않는다. 번역본마다 표현이 다를 수 있어 인용할 때 판본을 확인한다.',
  usage_examples = '[{"situation":"카톡","text":"이번 발표 나는 진짜 왼손은 거들 뿐이었음ㅋㅋ 다들 고생했어"},{"situation":"SNS 댓글","text":"결정타는 다른 사람이고 나는 거들었을 뿐이라는 말, 왼손은 거들 뿐 그 자체다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'e4esmtr7'
  and slug = '왼손은-거들-뿐'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

