-- 퀸카 챌린지 (fwvx7k7r / 퀸카-챌린지)
update public.memes set
  description = '퀸카 챌린지는 (여자)아이들이 2023년 발표한 미니 6집 ''I feel''의 타이틀곡 ''퀸카(Queencard)''의 포인트 안무를 활용한 틱톡 챌린지다. 사진을 찍는 듯한 ''찰칵'' 동작이 특징으로, 자신을 사랑하는 태도를 당당하게 표현하는 안무로 소개됐다. 배우, 가수, 개그우먼 등 다양한 분야의 연예인이 참여하며 확산됐다. 보도에 따르면 관련 해시태그 조회수는 틱톡에서 4억 4천만 회를 넘었고, 에스파, 르세라핌, 트와이스 등 아이돌 그룹도 동참했다.',
  origin = '(여자)아이들이 2023년 발매한 미니 6집 ''I feel''의 타이틀곡 ''퀸카'' 안무를 활용해 진행한 챌린지로, 2023년 6월 보도는 발매 후 틱톡, 릴스, 숏츠 등에서 이어졌다고 전했다. 소속사 동료인 비투비 서은광·이민혁, 배우 유선호, 개그우먼 이은지, 가수 이효리 등이 참여했다.',
  usage_note = '자신감이나 자기애를 주제로 한 콘텐츠, 혹은 사진 찍는 듯한 포즈를 활용한 숏폼 영상을 소개할 때 쓴다. 친구의 셀카 사진에 ''찰칵'' 포즈를 따라 해 보라고 권하는 식으로 가볍게 쓸 수 있다. 챌린지를 설명할 때는 ''찰칵'' 동작이 사진 촬영을 흉내 낸다는 점을 함께 적으면 이해가 쉽다.',
  caution = '아이돌 안무와 음원은 소속사와 작곡·편곡 저작권이 걸려 있어 원곡 음원을 붙인 영상을 무단으로 재업로드하면 문제가 될 수 있다. 챌린지에 참여한 연예인의 영상을 편집해 쓸 때는 본인 동의와 출처 표기를 확인한다. 조회수 4억 4천만은 보도 시점 기준 집계이므로 현재 수치처럼 인용하지 않는다.',
  usage_examples = '[{"situation":"카톡","text":"이 사진 찍어줘, 찰칵! 퀸카 챌린지 각ㅋㅋ"},{"situation":"SNS 댓글","text":"퀸카 챌린지 찰칵 포즈 따라 해봤는데 자존감 조금 올라감"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'fwvx7k7r'
  and slug = '퀸카-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

