-- BTS 다이너마이트 챌린지 (t8wncvva / BTS-다이너마이트-챌린지)
update public.memes set
  description = '방탄소년단의 디지털 싱글 ''다이너마이트''는 2020년 8월 21일 발매된 곡으로, 그룹이 데뷔 이래 처음 영어로만 소화한 노래다. 코로나19로 힘든 시기에 활력을 주려는 마음을 담았다고 소개됐다. 보그 코리아는 경쾌한 디스코 팝 곡이며 누구나 따라 할 수 있는 단순한 동작이 포함된 안무라고 전했다. 틱톡 뉴스룸에 따르면 ''#BTS_Dynamite'' 해시태그는 출시 후 이틀 남짓 만에 조회수 1억 회를 넘었고, 2020년 9월 1일에는 4억 8,400만 회를 넘었다.',
  origin = '2020년 8월 21일 방탄소년단 디지털 싱글 ''다이너마이트'' 발매와 함께 틱톡에서 ''#BTS_Dynamite'' 해시태그를 중심으로 확산됐다. 틱톡 뉴스룸은 이 해시태그가 이전 곡 ''ON''의 기록(약 3일에 1억 회)보다 빠르게 1억 회에 도달했다고 전했다.',
  usage_note = '2020년 글로벌 댄스 챌린지 사례나 방탄소년단의 영어곡 흥행을 설명할 때 쓰기 좋다. 특정 동작을 가리키기보다 곡 발매와 해시태그 확산을 함께 언급하는 맥락에서 쓰는 편이 정확하다.',
  caution = '안무의 세부 동작을 단정적으로 묘사하면 실제 안무와 어긋날 수 있으니 출처가 말하는 범위 안에서 언급한다. 조회수 집계는 발표 시점 기준이므로 현재 수치처럼 소개하지 않고 발표 연도를 함께 적는다. 공식 뮤직비디오나 안무 영상을 옮겨 쓸 때는 소속사와 제작사의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"2020년 댄스 챌린지 얘기","text":"2020년엔 다이너마이트 챌린지가 전 세계 틱톡을 휩쓸었지"},{"situation":"K팝 글로벌 흥행 댓글","text":"방탄 영어곡 다이너마이트 나온 해 틱톡 분위기 진짜 대단했음"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 't8wncvva'
  and slug = 'BTS-다이너마이트-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

