-- 토요일 토요일은 가수다 (urkxbj46 / 토요일-토요일은-가수다)
update public.memes set
  description = '‘토요일 토요일은 가수다’(토토가)는 MBC 예능 ‘무한도전’이 2014년 연말에 방송한 특집으로, 1990년대 가요계를 이끌었던 가수들을 다시 무대에 세운 기획이다. S.E.S., 김건모, 김현정, 엄정화, 터보, 쿨 등이 출연했으며, 2014년 12월 27일 방송분은 닐슨코리아 전국 기준 시청률 19.8%로 2014년 ‘무한도전’ 방송분 중 가장 높았다. 방송 직후 출연 가수들의 옛 노래가 온라인 음원 사이트 실시간 차트 상위권에 올랐고, 2015년 1월 3일 마지막 편은 닐슨코리아 기준 22.2%를 기록했다.',
  origin = '2014년 12월 20일 방송에서 준비 과정이 공개된 뒤 12월 27일 본 공연이 방송됐다. 2015년 1월 3일 방송된 마지막 편에서는 쿨, 소찬휘, 지누션, 조성모, 이정현, 엄정화, 김건모의 무대가 이어졌다.',
  usage_note = '1990년대 가수들의 노래가 음원 차트에서 다시 주목받는 현상을 설명하거나 복고 예능을 언급할 때 쓴다. 2014년 말 특정 방송 기획을 가리키는 말이므로 이후 나온 비슷한 기획과 헷갈리지 않도록 방송 연도를 함께 적는 것이 좋다.',
  caution = '출연 가수들의 근황이나 과거 활동을 단정해 말하면 사실과 다를 수 있으니 방송에서 확인된 내용만 언급한다. 시청률은 집계 기관과 지역 기준에 따라 수치가 다르므로 어느 기준인지 밝혀야 한다. 방송 장면이나 무대 영상을 옮겨 쓸 때는 방송사와 제작사의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"90년대 노래 얘기","text":"토토가 덕분에 90년대 노래들이 다시 차트에 올랐던 거 기억나지"},{"situation":"복고 예능 댓글","text":"토토가 이후로 옛날 가수 무대 보는 재미가 생겼다니까ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'urkxbj46'
  and slug = '토요일-토요일은-가수다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

