-- 개그콘서트 달인 (3pedrmwc / 개그콘서트-달인)
update public.memes set
  description = '‘달인’은 개그콘서트의 코너로, 2007년 12월 첫 방송된 뒤 프로그램에서 가장 오래 이어진 코너로 소개된다. 개그맨 김병만이 여러 분야의 달인을 맡아 말도 안 되는 실력을 우기며 웃음을 만들었고, 류담·노우진과 팀을 이뤘다. 2011년 6월 보도는 김병만이 굴삭기 위에서 두부를 써는 등 엉뚱한 달인 기술을 선보였다고 전했다. 초기에는 합성 사진을 들이밀며 달인을 우기는 방식이었고, 이후 가학 개그와 특이한 능력을 내세운 소재로 옮겨 갔다. 코너는 아이템을 바꿔 가며 이어졌다.',
  origin = '2007년 12월 KBS2 ‘개그콘서트’에서 처음 방송된 코너다. 2011년 3월 쿠키뉴스 보도는 방송 4년째 이어지는 최장수 코너라고 전했고, 김병만·류담·노우진 세 사람이 팀을 이뤄 일본 TBS 예능에도 초청 출연했다.',
  usage_note = '허세 섞인 전문가 흉내를 내거나 개그콘서트의 명물 코너를 회상할 때 쓴다. 과장된 자기소개나 엉뚱한 기술 자랑을 빗대는 표현으로 쓰면 자연스럽다. 코너 이름이 일반명사와 겹치므로 ‘개그콘서트 달인’처럼 프로그램명을 붙여 쓰는 편이 혼동이 없다.',
  caution = '김병만 개인의 실제 능력이나 직업을 깎아내리는 식으로 흉내 내면 실존 인물을 조롱하는 말이 될 수 있다. 방송 장면이나 편집 클립을 옮길 때는 방송사와 제작사의 저작권을 확인해야 한다. 코너 구성은 시기마다 달랐으므로 특정 편의 내용을 전체 코너의 특징처럼 말하지 않는다.',
  usage_examples = '[{"situation":"친구 허세 놀림","text":"너 방금 한 말 개그콘서트 달인 코너 그대로인데ㅋㅋ"},{"situation":"유튜브 댓글","text":"달인 코너 옛날 편 다시 보니까 김병만 연기 진짜 대단하다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '3pedrmwc'
  and slug = '개그콘서트-달인'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

