-- 뚜두뚜두 신드롬 (3pr36rva / 뚜두뚜두-신드롬)
update public.memes set
  description = '블랙핑크의 ‘뚜두뚜두’는 2018년 6월 15일 공개된 첫 미니앨범 ‘SQUARE UP’의 타이틀곡이자 뮤직비디오다. 공개 23시간 만에 조회수 3000만 회를 넘어 걸그룹 최단 기록을 세웠고, 33일 만에 2억 뷰를 돌파하며 K팝 그룹 최단 기록을 이어갔다. 공개 24시간 만에 가장 많은 조회수를 기록한 세계 뮤직비디오 2위에 올랐다는 보도도 있었으며, 2024년 5월 27일 기준 조회수 22억 회를 넘어 K팝 그룹 뮤직비디오 최초이자 최고 기록으로 소개됐다.',
  origin = '2018년 6월 15일 블랙핑크 첫 미니앨범 ‘SQUARE UP’의 타이틀곡 뮤직비디오로 공개됐다. 공개 후 23시간 만에 3000만 뷰를 넘었고, 68일 만에 3억 뷰를 돌파했다. 앨범은 2018년 6월 44개국 아이튠즈 앨범 차트 1위에 올랐다고 보도됐다.',
  usage_note = '걸그룹 유튜브 기록이나 2018년 K팝 뮤직비디오의 흥행을 말할 때 쓴다. 안무 커버나 패러디 얘기를 꺼낼 때도 자연스럽다. 조회수는 집계 시점에 따라 계속 변하므로 ‘2024년 5월 기준’처럼 시점을 밝혀 쓰는 것이 정확하다.',
  caution = '조회수 기록은 집계 시점과 기준이 기사마다 달라 특정 수치를 단정하면 틀릴 수 있다. 뮤직비디오 클립이나 안무 영상을 옮겨 쓸 때는 소속사와 제작사의 저작권을 확인해야 한다. 패러디 영상은 원곡의 의도와 맞지 않을 수 있으니 조롱이나 성적 맥락으로 쓰지 않도록 주의한다.',
  usage_examples = '[{"situation":"K팝 기록 얘기","text":"뚜두뚜두 3000만 뷰를 23시간 만에 찍은 거 지금 봐도 대단함"},{"situation":"커버 영상 댓글","text":"뚜두뚜두 커버 영상 보고 왔는데 안무 살린 거 보니까 원곡 생각 많이 나네"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '3pr36rva'
  and slug = '뚜두뚜두-신드롬'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

