-- 후크송 열풍 (4pyvubb8 / 후크송-열풍)
update public.memes set
  description = '‘후크송’은 짧고 중독성 있는 후렴을 반복하는 곡을 가리키는 말로, 2000년대 후반 가요계에서 이 흐름이 유행한 현상을 뜻한다. 2010년 쿠키뉴스 기사는 당시 기준 2년 전부터 후크송 열풍이 불었고, 원더걸스의 ‘Tell Me’를 시작으로 반복적 멜로디와 가사를 앞세운 곡들이 잇따라 나왔다고 전했다. 같은 기사는 이 흐름이 예전만큼 주목받지 못하더라도 여전히 흔히 찾아볼 수 있다고 봤다. 음악 사이트 멜론과 롤링스톤은 ‘Tell Me’를 K팝 역대 명곡으로 꼽으며 이 곡이 ‘후크송 트렌드’를 촉발했다고 평가했다.',
  origin = '2007년 9월 13일 발매된 원더걸스의 ‘Tell Me’가 출발점으로 꼽힌다. 2007년 11월 Korea Times는 이 곡의 중독적인 후렴과 따라 하기 쉬운 안무가 전국적 반응을 얻었다고 전했고, 2010년 7월 쿠키뉴스는 이 곡 이후 후크송 열풍이 불었다고 정리했다.',
  usage_note = '2000년대 후반 아이돌 음악의 흐름을 설명하거나, 짧은 후렴이 반복되는 곡의 특징을 말할 때 쓴다. 특정 곡 하나보다 흐름 전체를 가리키는 말이므로 ‘원더걸스 Tell Me 이후의 후크송 열풍’처럼 기점을 함께 밝히는 편이 정확하다.',
  caution = '‘후크송’은 학술 용어가 아니라 대중음악 기사와 평론에서 쓰인 말이므로 정의를 단정하지 않는다. 열풍의 기점과 범위는 기사마다 다르므로 특정 연도를 확정적으로 쓰면 틀릴 수 있다. 곡의 가사나 음원을 길게 인용하면 저작권 문제가 생기므로 제목과 흐름만 언급한다.',
  usage_examples = '[{"situation":"음악 얘기","text":"후렴만 계속 반복되는 노래 보면 후크송 열풍 시절 생각나지ㅋㅋ"},{"situation":"옛날 아이돌 댓글","text":"텔미 나오던 시절 후크송 열풍 진짜 대단했음"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '4pyvubb8'
  and slug = '후크송-열풍'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

