-- 삼시세끼 차줌마 (5k9bbh4q / 삼시세끼-차줌마)
update public.memes set
  description = 'tvN 예능 ‘삼시세끼’ 어촌편에서 배우 차승원은 뛰어난 요리 실력과 부지런함으로 ‘차줌마’라는 별명을 얻었다. 만재도에서 앞치마를 두르고 요리와 살림을 도맡았고, 방송에서는 잔소리왕, 김치왕, 요리왕, ‘섹시한 부엌데기’ 같은 표현으로 이 캐릭터가 설명됐다. 카리스마 있는 배우라는 기존 이미지와 다른 모습이 반전으로 주목받았고, 2015년 2월에는 OSEN이 ‘차줌마 특집’ 기사를 이어 냈다. 유해진과 중년 부부 같은 콤비라는 평가도 함께 나왔다.',
  origin = '2015년 1월 23일 tvN ‘삼시세끼’ 어촌편 첫 방송과 함께 화제가 됐다. 텐아시아는 1월 26일 기사에서 차승원이 ‘차줌마’ 별명을 얻었다고 전했고, OSEN은 2015년 2월 20일 기사에서 나영석 PD가 자막으로 그를 ‘차줌마’라고 명명했다고 소개했다.',
  usage_note = '요리나 살림 솜씨가 뜻밖이라 놀랄 때 ''차줌마급''이라고 빗대어 쓴다. 평소 무뚝뚝해 보이던 사람이 생활력을 드러낼 때 가볍게 붙이는 용도로 적합하다. 방송을 본 적 없는 사람에게는 어촌편 맥락을 짧게 덧붙이면 의미가 잘 전달된다.',
  caution = '방송 출연자를 놀리는 용도로 쓰면 실제 배우의 이미지와 충돌할 수 있으므로 칭찬의 맥락에서 쓴다. 방송 장면 캡처나 클립을 공유할 때는 제작사의 저작권을 고려해야 한다. 방송이 2015년의 것이므로 현재 출연자의 근황을 함께 말할 때는 따로 확인이 필요하다.',
  usage_examples = '[{"situation":"카톡","text":"저 사람 요리 실력 완전 차줌마급 반전이다, 무뚝뚝한 줄 알았더니"},{"situation":"SNS 댓글","text":"살림까지 저렇게 잘하면 차줌마 소리 들을 만하네"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '5k9bbh4q'
  and slug = '삼시세끼-차줌마'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

