-- TWS 따룸 챌린지 (6rb3wwc4 / TWS-따룸-챌린지)
update public.memes set
  description = 'TWS가 2026년 4월 27일 발매한 미니 5집 ''NO TRAGEDY''의 타이틀곡 ''널 따라가 (You, You)''의 후렴 훅에 맞춘 포인트 안무를 따라 하는 챌린지다. 어깨와 발을 흔드는 단순한 동작이 특징으로, 앞서 2025년 ''앙탈 챌린지''가 온라인에서 크게 화제가 된 뒤 이어진 흐름으로 소개됐다. 2026년 5월 한국일보 영문 기사는 이 챌린지들이 그룹의 정체성을 만들고 있다고 평가하면서, 온라인 반응이 앨범 판매량과 더 큰 공연장 진출로 이어졌고 이 앨범이 첫 주 약 111만 장을 기록했다고 전했다.',
  origin = '2026년 4월 27일 TWS 미니 5집 ''NO TRAGEDY''가 발매되며 타이틀곡의 ''따룸 챌린지''가 등장했다. 머니투데이는 4월 28일 기사에서 이를 ‘앙탈’ 다음의 챌린지로 소개했고, 한국일보는 5월 14일 이 챌린지가 온라인에서 주목받고 있다고 전했다. 앞선 ‘앙탈 챌린지’는 2025년에 화제가 됐다.',
  usage_note = 'TWS 컴백이나 ''앙탈'' 이후의 챌린지 흐름을 설명할 때 연결해서 쓴다. 후렴 훅 구간의 짧은 포인트 안무를 따라 하는 영상을 언급할 때 가볍게 붙이기 좋다. 곡 제목 ‘널 따라가’와 챌린지 이름이 다르므로 글에서는 ‘따룸 챌린지’처럼 챌린지 명칭을 분명히 적는 편이 낫다.',
  caution = '챌린지 안무는 소속사와 아티스트가 만든 콘텐츠이므로 영상을 재게시할 때 저작권과 초상권을 함께 고려한다. 챌린지 참여를 놀리는 방향으로 쓰면 아티스트 팬덤과 충돌할 수 있다. 챌린지 열기는 빠르게 바뀌므로 현재 유행 여부는 최신 자료로 다시 확인한다.',
  usage_examples = '[{"situation":"카톡","text":"이번에 따룸 챌린지 따라 하다가 무릎 나갈 뻔했다"},{"situation":"SNS 댓글","text":"TWS 따룸 챌린지 후렴만 나오면 자동으로 몸이 움직인다"}]'::jsonb,
  origin_year = 2026,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '6rb3wwc4'
  and slug = 'TWS-따룸-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

