-- 김동문-하태권 배드민턴 복식 금메달 (dqq2mw57 / 김동문-하태권-배드민턴-복식-금메달)
update public.memes set
  description = '김동문과 하태권은 초등학교 시절부터 함께 라켓을 잡은 뒤 원광대와 삼성전기를 거치며 오랜 기간 남자복식 파트너로 활동한 배드민턴 선수다. 두 사람은 2004년 8월 20일 아테네 올림픽 남자복식 결승에서 선배 이동수·유용성 조를 2대0으로 꺾고 금메달을 땄다. 이 결승은 한국 선수끼리 맞붙어 금메달과 은메달을 나눠 가진 대회로 기록됐다. 1992년 남자복식이 정식 종목이 된 뒤 한 나라가 금·은메달을 모두 가져간 첫 사례로 보도됐다. 기사에 따르면 김동문은 혼합복식에 시간을 쏟느라 남자복식 준비가 부족했던 점을 하태권에게 미안해했다.',
  origin = '2004년 8월 20일 아테네 올림픽 배드민턴 남자복식 결승에서 김동문·하태권 조가 이동수·유용성 조를 15-11, 15-4로 누르고 금메달을 땄다. 김동문은 1996년 애틀랜타 올림픽 혼합복식 금메달에 이어 두 번째 금메달을 얻었고, 서울신문은 두 사람이 초등학교 4학년 때 나란히 라켓을 잡은 단짝이라고 소개했다.',
  usage_note = '한국 배드민턴 남자복식의 역사를 이야기하거나 2004년 아테네 대회의 한국 대결 결승을 언급할 때 쓴다. 두 선수의 오랜 호흡을 강조하는 맥락에서 인용하기 좋다. 혼합복식 등 다른 종목 기록과 섞이지 않도록 종목을 함께 밝힌다.',
  caution = '실제 선수의 경기 기록을 다루므로 사실 관계는 당시 보도와 대한배드민턴협회 기록을 확인해 인용한다. 결승 장면을 놀림의 소재로 쓰면 당사자와 가족에게 불편할 수 있다. 영상 클립을 공유할 때는 방송사 저작권을 고려한다.',
  usage_examples = '[{"situation":"카톡","text":"아테네 때 한국 대 한국 결승 다시 보는데 김동문 하태권 호흡 진짜 좋았다"},{"situation":"SNS 댓글","text":"2004년 아테네 남복 결승은 금은 다 한국이 가져간 경기라 역사에 남을 만하다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'dqq2mw57'
  and slug = '김동문-하태권-배드민턴-복식-금메달'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

