-- 오마카세 열풍 (dzxy69n7 / 오마카세-열풍)
update public.memes set
  description = '오마카세는 요리사에게 메뉴 구성을 맡긴다는 뜻의 일본어로, 국내에서는 셰프가 정한 코스 요리를 가리키는 말로 쓰인다. 2022년 무렵에는 예약 경쟁이 치열해 ''스강신청(스시+수강신청)''이라는 신조어까지 생겼다. 2023년에는 고물가 속에서도 즐길 수 있는 작은 사치로 주목받아 매장이 급증했으며, 스시를 넘어 디저트·중식·한식 등으로 장르가 넓어졌다. 인증샷을 남기려는 SNS 문화와 맞물려 확산된 외식 트렌드이며, 스시 전문점에서 시작된 식문화가 파인다이닝 전반으로 번진 흐름을 보여주는 사례다.',
  origin = '일본어 ‘오마카세’는 셰프에게 요리를 맡긴다는 의미로, 일식당에서 쓰이던 말이다. 2023년 3월 데일리안은 국내에 오마카세를 처음 선보인 곳으로 신라호텔과 조선호텔을 꼽았고, 2022년 2월 GQ Korea는 코로나19로 일본 여행이 막히며 스시 오마카세가 부상했다는 셰프의 설명을 전했다.',
  usage_note = '고가 외식이나 파인다이닝 예약 경쟁을 가볍게 묘사할 때 쓴다. 특정 음식이 유행하며 가격과 대기가 높아진 상황을 설명하는 맥락에서 적합하다. 스시 외의 디저트·중식 오마카세처럼 장르를 넓혀 쓰는 것도 일반적이다.',
  caution = '오마카세는 한 끼에 수십만 원에 이르기도 해 과시나 소비 부추김으로 읽힐 수 있으므로 경제적 여건을 비하하는 식으로 쓰지 않는 것이 좋다. 가격과 구성은 매장마다 크게 다르므로 특정 업장의 가격을 단정해 인용하지 않는다. 인용한 수치는 2023년 보도 시점 기준이라 지금의 상황과 다를 수 있다.',
  usage_examples = '[{"situation":"주말 예약 후기","text":"이번 주말 오마카세 예약 성공ㅋㅋ 이게 바로 스강신청의 힘이네"},{"situation":"외식 트렌드 댓글","text":"고물가라더니 오마카세는 여전히 웨이팅이 살벌하네요"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'dzxy69n7'
  and slug = '오마카세-열풍'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

