-- 아프냐 나도 아프다 (h4w6zhbr / 아프냐-나도-아프다)
update public.memes set
  description = '2003년 MBC 드라마 ‘다모’ 1회에서 종사관 황보윤이 채옥에게 건넨 대사로, “아프냐”는 물음에 채옥이 답하자 황보윤이 “나도 아프다”고 말하며 수하를 누이처럼 아낀다는 마음을 드러낸다. iMBC는 이 드라마가 2003년 방송 당시 수많은 ‘드라마 폐인’을 양산하며 신드롬을 일으켰다고 소개했다. 한 커뮤니티 글은 이 열풍에서 ‘다모폐인’이라는 말까지 나왔고 이 대사가 패러디될 만큼 유명하다고 적었다. 2026년 11월 6일에는 SBS 예능 ‘비서진’에서 이서진과 하지원이 이 대사를 23년 만에 재현했다.',
  origin = '2003년 MBC 드라마 ‘다모’ 1회에서 나온 대사다. iMBC는 이 장면을 1회 대사로 소개했고, 커뮤니티 글에 따르면 채옥이 다쳐 돌아왔을 때 황보윤(이서진)이 치료하며 건넨 말이다. 2026년 11월 6일 방송된 SBS ‘비서진’ 10회의 싱가포르 뒤풀이에서 이서진과 하지원(채옥 역)이 이 대사를 재현했다.',
  usage_note = '공감이나 위로를 장난스럽게 건넬 때 원작 대사를 인용하는 식으로 쓴다. 상대가 힘들어 보일 때 짧게 되받아치는 농담으로 적합하다. 드라마 이야기나 이서진·하지원 예능 재현 콘텐츠를 다룰 때 언급하기 좋다.',
  caution = '드라마 장면 클립과 캡처를 무단으로 올리면 저작권 문제가 될 수 있으므로 대사 인용에 그친다. 배우의 사생활이나 예능 촬영 뒷이야기를 과장해 단정하지 않는다. 2003년 방송이라 세대에 따라 장면을 알지 못할 수 있으니 맥락 설명을 덧붙이는 것이 좋다.',
  usage_examples = '[{"situation":"카톡 대화","text":"많이 힘들었지... 아프냐, 나도 아프다ㅋㅋ"},{"situation":"SNS 댓글","text":"다모 명장면 재현 봤는데 이 대사는 여전히 찡하네요"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'h4w6zhbr'
  and slug = '아프냐-나도-아프다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

