-- LOVE DIVE 챌린지 (m7yfh2fa / LOVE-DIVE-챌린지)
update public.memes set
  description = '2022년 4월 5일 발매된 아이브의 두 번째 싱글 타이틀곡 ''LOVE DIVE''를 배경음악으로 한 틱톡 챌린지다. 챌린지가 공개된 지 일주일 만에 ''#LOVEDIVE'' 해시태그가 붙은 영상 조회수가 2억 뷰를 훌쩍 넘었다는 보도가 나왔다. 이 곡은 2022년 틱톡에서 가장 사랑받은 배경음악 가운데 하나로 소개되었고, 아이브 공식 틱톡 계정도 #LOVEDIVEchallenge 해시태그를 단 영상을 올렸다. 정식 음원이 아니라 프로모션 비디오에 쓰인 음향을 활용한 ''디어큐피드챌린지''도 함께 인기를 끌었다는 보도가 있다.',
  origin = '아이브의 두 번째 싱글 앨범 타이틀곡으로 2022년 4월 5일 공개됐다. 2022년 8월 iMBC 보도는 챌린지 공개 일주일 만에 해시태그 영상 조회수가 2억 뷰를 넘었고, 프로모션 비디오의 음향을 쓴 챌린지도 나왔다고 전했다.',
  usage_note = '커버댄스나 챌린지 영상을 소재로 삼을 때 언급하면 자연스럽다. 2022년 틱톡에서 사랑받은 음원으로 소개하는 회고 콘텐츠에서 활용하기 좋다. 아이브 음악과 챌린지를 함께 다루는 글에서 맥락을 설명하는 용도로 적합하다.',
  caution = '안무 영상은 음원과 뮤직비디오의 저작권이 걸려 있어 원본 클립을 무단으로 옮기지 않는다. 틱톡 챌린지 영상은 일반 이용자의 창작물이 많으므로 특정 이용자를 조롱하는 식으로 편집하지 않는다. 조회수와 순위 수치는 2022년 보도 시점 기준이므로 지금 기준으로 단정하지 않는다.',
  usage_examples = '[{"situation":"커버댄스 댓글","text":"러브다이브 챌린지 이 파트 따라 추기 딱 좋네요ㅋㅋ"},{"situation":"2022년 회고 글","text":"2022년 틱톡 챌린지 얘기하면 러브다이브를 빼놓을 수 없지"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'm7yfh2fa'
  and slug = 'LOVE-DIVE-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

