-- 흑당버블티 대란 (mfm9qqd7 / 흑당버블티-대란)
update public.memes set
  description = '대만 흑당 버블티 브랜드 ''타이거슈가''가 2019년 3월 국내에 입점하면서 흑당 열풍이 시작됐다는 보도가 있다. 설탕보다 깊고 진한 단맛을 내는 흑당은 음료를 넘어 과자와 빙수 등 식품 전반으로 번졌으며, 해태제과는 ''맛동산''의 두 번째 맛으로 흑당을 선택했다. 디저트 신제품도 잇따라 나왔다. 한 프랜차이즈는 흑당 버블티가 출시 후 20초에 한 잔꼴로 팔린 셈이라고 밝혔다. 한편 유행을 좇아 비슷한 브랜드가 우후죽순 늘어나는 ''미투 현상''에 대한 우려도 함께 나왔다. 2019년 음료 시장의 유행을 보여 주는 사례다.',
  origin = '흑당은 정제되지 않은 설탕의 일종으로 색이 짙고 풍미가 깊은 재료다. 대만에서 인기를 끈 흑당 버블티가 국내에 들어오며 유행이 시작됐고, 2019년 3월 대만 브랜드 타이거슈가의 국내 입점이 계기로 보도됐다.',
  usage_note = '유행 음료의 인기를 얘기할 때 대표 예시로 드는 용도로 쓴다. 2019년 음료 트렌드를 회고하는 글에서 사례로 언급하기 좋다. 한때 빠르게 퍼졌다가 흐름이 바뀐 메뉴를 설명할 때도 어울린다.',
  caution = '단맛이 강한 음료이므로 건강과 연결해 과장된 단정을 하지 않는다. 특정 브랜드나 매장을 비방하는 식으로 쓰지 않는다. 판매 속도와 인기 수치는 2019년 보도 시점 기준이라 지금 상황과 다를 수 있다.',
  usage_examples = '[{"situation":"카페 대화","text":"여기 흑당 버블티 아직도 웨이팅 있어? 2019년 그때 생각난다ㅋㅋ"},{"situation":"음료 리뷰 댓글","text":"흑당 특유의 진한 단맛 그대로네요. 2019년 열풍 그때 감성이다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
