-- 우리 친구 아이가 (mvt4pny2 / 우리-친구-아이가)
update public.memes set
  description = '''우리 친구 아이가''는 2001년 개봉한 곽경택 감독의 영화 ''친구''에서 나온 대사를 바탕으로 한 말이다. 영화 속에서 친구 사이의 의리와 우정을 강조하는 표현으로 쓰였고, 한국교육신문 2001년 4월 글은 극 중 "개안타, 우린 친구 아이가"라는 대사가 ''친구''라는 말의 의미를 드러낸다고 해석했다. 이투데이는 개봉 당시 ''친구 아이가'', ''니가 가라 하와이'', ''고마해라 마이 묵었다 아이가'' 같은 유행어가 나왔고 청소년관람불가 영화임에도 큰 관객을 모았다고 전했다. 지큐 코리아는 이 유행어들이 지금까지 회자되며 전국 800만 관객을 동원한 영화라고 소개했다.',
  origin = '2001년 영화 ''친구''(곽경택 감독)의 대사다. 한국교육신문 2001년 4월 글은 "개안타, 우린 친구 아이가"를 인용했고, 이투데이는 ''친구 아이가''를 개봉 당시 유행어로 소개했다. 제목과 같은 ''우리 친구 아이가'' 형태의 정확한 대사 위치와 장면은 확인하지 못했다.',
  usage_note = '친구끼리 의리와 끈끈함을 장난스럽게 드러낼 때 쓰기 좋다. 오랜 친구 모임에서 분위기를 띄우거나, 서로를 챙기는 사이라는 점을 가볍게 강조할 때 자연스럽다. 진지한 고백보다는 농담이 섞인 말투로 건네는 편이 어울린다.',
  caution = '영화 ''친구''는 폭력과 범죄를 다룬 누아르라서, 대사만 떼어 쓰면 맥락과 달리 과격하게 읽힐 수 있다. 경상도 사투리를 흉내 내며 지역을 희화화하는 농담으로 쓰면 지역 비하로 받아들여질 수 있으니 피하는 것이 좋다. 영화 장면 영상을 직접 편집해 올릴 때는 배급사의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"오랜 친구 단체 채팅방에서 누군가 먼저 안부를 물었을 때","text":"역시 우리 친구 아이가, 이 시간에도 제일 먼저 연락 주네ㅋㅋ"},{"situation":"친구 결혼식 축사를 준비하며 분위기를 가볍게 띄울 때","text":"우리 친구 아이가, 오늘은 신랑 흉은 조금만 보자는 게 우리 사이의 예의 아니겠나."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'mvt4pny2'
  and slug = '우리-친구-아이가'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

