-- 곽윤기 뒷선수 시점 (mx952b7p / 곽윤기-뒷선수-시점)
update public.memes set
  description = '''곽윤기 뒷선수 시점''은 2022년 베이징 동계올림픽 쇼트트랙 남자 5000m 계주 준결승에서 곽윤기 선수가 허리를 숙여 다리 사이로 뒤 선수의 위치를 확인한 장면에서 비롯된 밈이다. 이 동작을 단순하게 그린 그림이 온라인 커뮤니티에 퍼지며 ''뒷선수 시점''이라는 이름으로 불렸다. 곽윤기 선수가 직접 트랙을 돌며 같은 동작을 재연한 영상을 올리면서 팬들의 패러디 놀이로 이어졌다. 곽윤기 선수가 ''다들 그만''이라는 글과 함께 영상을 올리며 웃음으로 받아들여 밈이 더 널리 퍼졌다.',
  origin = '2022년 2월 11일 베이징 동계올림픽 쇼트트랙 계주 준결승 장면이 출발점이다. 그림의 원작자는 밴쿠버 동계올림픽이 열린 해에 태어난 12세 어린이로 보도됐다. 그림이 처음 게시된 커뮤니티와 정확한 게시일은 열어 본 기사에서 확인하지 못했다.',
  usage_note = '계주처럼 뒤를 확인해야 하는 상황이나, 과하게 주변을 신경 쓰고 견제하는 모습을 유쾌하게 비유할 때 쓴다. 상대의 움직임을 계속 살피는 사람에게 던지는 농담 섞인 댓글로도 어울린다. 실제 경기 설명보다는 가볍고 웃긴 비유로 쓰는 것이 자연스럽다.',
  caution = '실제 경기 장면과 선수 본인이 응한 재연 영상을 바탕으로 한 밈이므로, 선수의 동작을 과장해 조롱하는 식으로 쓰면 무례하게 읽힐 수 있다. 그림 원작자가 어린이로 보도됐으므로 그림을 가져다 쓸 때는 원작자 표기와 허락 여부를 확인해야 한다. 중계 화면을 편집해 재사용할 때는 방송사의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"동료가 회의 중 옆자리 눈치를 계속 살필 때","text":"자꾸 옆자리만 훔쳐보는 거 보니까 곽윤기 뒷선수 시점 찍는 중이네ㅋㅋ"},{"situation":"경쟁 상대의 움직임만 계속 확인하는 친구에게","text":"뒷선수 시점으로 계속 확인하는 중? 이제 그냥 앞으로 치고 나가도 되지 않을까."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'mx952b7p'
  and slug = '곽윤기-뒷선수-시점'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

