-- 1일1깡 챌린지 (mxd7cr4q / 1일1깡-챌린지)
update public.memes set
  description = '''1일 1깡''은 비가 2017년 발표한 노래 ''깡''을 하루에 한 번은 봐야 한다는 뜻으로 쓰는 말이다. 발매 당시에는 과장된 가사와 안무 때문에 혹평을 받았으나, 2020년 상반기 패러디 영상과 뮤직비디오 댓글이 화제가 되며 조롱과 유쾌함이 섞인 역주행이 일어났다. 비는 2020년 5월 16일 MBC ''놀면 뭐하니?''에 출연해 ''1일 3깡은 해야 한다''고 말하며 이 반응을 쿨하게 받아들였다. 이후 6월 4일에는 하이어뮤직 소속 가수들과 함께한 ''깡'' 리믹스 버전이 발표됐고, 비는 농심 새우깡 모델로도 선정됐다. 비즈워치는 이 현상을 ''밈 마케팅''의 사례로 다뤘다.',
  origin = '2017년 발매된 비의 노래 ''깡''이 2020년 상반기 역주행하며 밈이 됐다. 더팩트는 2020년 5월 16일 비가 MBC ''놀면 뭐하니?''에 출연한 것이 ''1일 1깡'' 열풍 덕이었다고 전했고, 보그 코리아는 2019년 한 유튜브 커버 영상이 주목받으며 인기가 시작됐다고 적었다. 패러디가 처음 시작된 정확한 채널은 확인하지 못했다.',
  usage_note = '매일 반복해서 보게 되는 과장된 무언가를 가볍게 말할 때 쓴다. 중독성이 강한 콘텐츠를 두고 ''1일 1깡''이라고 하면 반복 소비를 농담처럼 표현할 수 있다. 노래를 진지하게 추천하는 맥락보다는 웃음을 섞은 자조 섞인 표현으로 쓰는 편이 자연스럽다.',
  caution = '처음 밈은 노래의 허세 섞인 가사와 안무를 조롱하는 의미로 시작됐으므로, 비를 비하하는 농담으로 번지지 않게 주의한다. 비가 조롱 섞인 반응을 쿨하게 받아들인 사례가 보도됐지만, 모든 사람이 같은 태도를 갖는 것은 아니다. 노래 영상이나 뮤직비디오 클립을 재편집해 올릴 때는 저작권 침해가 될 수 있다.',
  usage_examples = '[{"situation":"좋아하는 채널의 영상을 매일 챙겨 보는 친구에게","text":"너 그 채널 1일 1깡 하는 거지? 매일 챙겨 보는 거 인정?"},{"situation":"같은 콘텐츠를 반복해서 돌려 보는 사람에게 농담할 때","text":"오늘도 1일 1깡 했냐? 이 정도면 생활 습관이다."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'mxd7cr4q'
  and slug = '1일1깡-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

