-- 방탄소년단 '쩔어' (ncrbuvqt / 방탄소년단-쩔어)
update public.memes set
  description = '''쩔어''는 방탄소년단이 2015년 4월 29일 발매한 EP ''화양연화 pt.1''에 실린 곡으로, 영문 제목 ''Dope''로도 알려져 있다. 위키백과에 따르면 이 곡은 후속 활동곡으로 2015년 6월 24일 뮤직비디오가 공개됐고, 유튜브 리액션 영상이 잇따르며 해외에서 관심을 모았다. 뮤직비디오는 방탄소년단 최초로 유튜브 조회수 1억 뷰를 넘긴 영상이 됐다. 2021년 텐아시아는 전문 댄서 4인이 유튜브 리액션 영상에서 이 곡의 안무를 레전드라고 호평했다고 전했다. 2018년 더블유 코리아 기사는 해외 미디어 평론이 이 곡을 세대 문제를 다룬 메시지로 언급했다고 함께 소개했다.',
  origin = '2015년 4월 29일 발매된 EP ''화양연화 pt.1''의 수록곡으로, 영문 위키백과는 ''Dope''가 6월 24일 후속 활동곡으로 뮤직비디오를 공개했다고 적는다. 안무는 키원 마드리드가 만들었고 뮤직비디오는 GDW가 제작했다.',
  usage_note = '방탄소년단의 초기 인기 계기를 이야기하거나 아이돌 안무의 완성도를 칭찬할 때 쓴다. 리액션 영상으로 해외에서 관심을 모은 곡이라는 맥락을 말할 때 인용하기 좋다. 그룹의 대표곡으로 단정하기보다 초기 활동기의 화제곡으로 소개하는 편이 정확하다.',
  caution = '리액션 영상은 원곡 뮤직비디오를 재생하는 방식이 많아, 영상을 내려받아 다시 올리면 음원과 영상의 저작권 문제가 생긴다. 해외 리액션 사례의 조회수와 반응은 시점마다 다르므로 현재 수치로 단정하지 않는 것이 좋다. 안무를 다른 아이돌과 비교하며 깎아내리는 댓글은 팬 사이 갈등을 부를 수 있다.',
  usage_examples = '[{"situation":"방탄소년단의 초기 곡 이야기를 나눌 때","text":"쩔어 안무 지금 봐도 레전드다. 리액션 영상 보고 해외에서 먼저 반응이 왔던 곡이지."},{"situation":"댄스 커버 영상 댓글에서","text":"이 커버 보니까 쩔어 원곡 안무가 얼마나 어려운지 다시 느껴진다ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ncrbuvqt'
  and slug = '방탄소년단-쩔어'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

