-- 침대는 과학이다 (npmz6vdx / 침대는-과학이다)
update public.memes set
  description = '''침대는 과학이다''는 에이스침대의 대표 광고 카피다. 1993년 광고에서 ''침대는 가구가 아니라 과학입니다''라는 문구가 크게 화제가 되며 브랜드 이미지를 굳혔다. 혼수를 준비하는 신혼부부들 사이에서 ''침대는 과학''이라는 농담이 오갈 정도로 널리 퍼졌다. 이후 ''○○는 과학이다'' 형식을 빌려 쓰는 말장난의 원형으로도 자주 인용된다. 2015년 기사에서는 이 카피가 신혼부부들 사이에서 농담으로 쓰일 만큼 알려졌다고 짚었다. 2023년 뉴시스 기사는 이 카피를 1980~1990년대 광고 카피 재해석 사례로 다시 소개했다.',
  origin = '1993년 에이스침대 광고에서 쓰인 카피다. 2015년 기사는 이 광고 문구를 ''침대는 가구가 아니라 과학입니다''로 소개했다. 광고 출연자와 방영 채널 등 세부 사항은 열어 본 기사에서 확인하지 못했다.',
  usage_note = '논리가 비약하지만 그럴듯하게 정당화하는 상황을 재치 있게 말할 때 쓴다. 근거 없이 확신에 찬 주장을 농담으로 받아칠 때도 잘 맞는다. 제품을 실제로 추천하는 말보다는 과장된 자신감을 웃음으로 넘기는 용도로 쓰는 편이 어울린다.',
  caution = '1993년 광고 카피를 원형으로 하는 말이라, 현재 에이스침대 제품의 성능이나 시장 위치를 보장하는 말로 읽히면 안 된다. 2015년 기사는 당시 매출 정체를 짚으며 이 카피의 위상이 흔들린다고 분석했으므로 시기별 상황이 다를 수 있다. 광고 영상 클립을 편집해 사용할 때는 광고주의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"친구가 엉뚱한 이유로 비싼 물건을 샀다고 우길 때","text":"그 이유라면 침대는 과학이다. 논리는 잘 모르겠는데 일단 맞는 말 같아."},{"situation":"단체 채팅에서 근거 없는 주장을 받아칠 때","text":"''그건 과학이다''로 끝내지 말고 근거를 좀 대봐ㅋㅋ 침대는 과학이긴 하지만."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'npmz6vdx'
  and slug = '침대는-과학이다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

