-- 눈 내리는 밤 (ntryvds9 / 눈-내리는-밤)
update public.memes set
  description = '''눈 내리는 밤''은 사진 한 장을 AI 카메라 앱에 넣어 눈 내리는 겨울 밤이나 설경 배경의 감성 사진으로 바꾸는 놀이다. 한국경제에 따르면 메이투는 2025년 10월 28일, 스노우는 10월 31일부터 ''AI 겨울 3컷'' 콘텐츠를 서비스했고, 이후 SNS에서 유행했다. 가수 박재범과 유튜버 충주맨이 같은 방식의 콘텐츠를 올려 관심을 키웠다. 블로그 등에서는 메이투의 ''눈 내리는 밤'' 필터로 소개되기도 했다. 기사는 사진 한 장을 넣으면 1분 안팎에 결과물이 나온다고 전했다. 해외 매체 Geo News도 2025년 11월 12일 메이투의 ''AI snow scene'' 효과가 세계적으로 주목받았다고 보도했다.',
  origin = '2025년 10월 28일 메이투가, 10월 31일 스노우가 ''AI 겨울 3컷'' 서비스를 시작한 뒤 SNS에서 확산됐다. 한국경제는 2025년 11월 9일 보도에서 네이버 데이터랩 기준 ''AI 겨울'' 검색량이 10월 31일 최고치(100)를 기록했다고 전했다. 메이투 관계자는 일본에서 먼저 서비스해 반응이 좋아 한국에서도 출시했다고 밝혔다.',
  usage_note = '겨울 감성 프로필 사진이나 브이로그 썸네일을 만들 때 참고하는 놀이로 쓴다. 실제로 눈이 오지 않는 날에 분위기만 연출했다는 농담으로 ''방구석 설원''이라고 부르면 자연스럽다. 결과물을 자랑하는 게시물에 가볍게 반응할 때도 어울린다.',
  caution = 'AI로 만든 사진은 실제 여행이나 촬영을 한 것처럼 보여 주면 오해를 부를 수 있으니 합성 사실을 밝히는 편이 좋다. 타인의 사진을 무단으로 변환해 올리면 초상권 문제가 생길 수 있으므로 본인 사진이나 동의를 받은 사진만 쓴다. 앱의 이용 약관과 유료 구독 조건도 함께 확인해야 한다.',
  usage_examples = '[{"situation":"겨울 프로필 사진을 바꾸며 친구에게 자랑할 때","text":"눈 내리는 밤 필터 돌려봤는데 실제로 삿포로 간 줄 알겠지?ㅋㅋ"},{"situation":"친구가 AI 겨울 사진을 올렸을 때 댓글로","text":"방구석 설원 인생샷 인정. 근데 진짜 눈은 언제 보러 갈 거야?"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ntryvds9'
  and slug = '눈-내리는-밤'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

