-- DASH 챌린지 (p9n65wbu / DASH-챌린지)
update public.memes set
  description = '''DASH''는 엔믹스가 2024년 1월 15일 발매한 미니 앨범 ''Fe3O4: BREAK''의 타이틀곡이다. 발매 후 2주가 채 되지 않은 기간에 음악방송 1위를 네 차례 기록했다. DASH 챌린지는 엔믹스 멤버가 다른 그룹 아이돌과 번갈아 안무를 추는 방식으로 SNS에서 퍼졌고, 스포츠키다는 아이브 가을, 있지 류진, 르세라핌 카즈하, 트와이스 지효와 사나 등이 참여했다고 전했다. 설윤이 사나와 함께한 영상은 팬들 사이에서 화제가 됐다. 스포츠경향은 이 곡을 그룹만의 ''MIXX POP'' 장르로 소개하며 다이내믹한 전개가 매력이라고 전했다.',
  origin = '2024년 1월 15일 엔믹스의 미니 앨범 ''Fe3O4: BREAK''와 타이틀곡 ''DASH''가 발매되면서 시작됐다. 1월 24일 쇼챔피언에서 첫 음악방송 1위를 했고, 1월 28일 인기가요에서 네 번째 1위를 기록했다. 챌린지의 정확한 시작 게시물과 참여자 수는 열어 본 출처에서 확인하지 못했다.',
  usage_note = '아이돌 그룹의 챌린지 열풍을 이야기할 때 대표 사례로 꺼내기 좋다. 챌린지 영상에 함께 참여하자고 권하는 댓글로 쓸 수 있다. 특정 멤버의 참여를 칭찬하는 맥락에서 쓰면 자연스럽다.',
  caution = '챌린지 영상은 원곡 음원과 안무 영상이 함께 쓰이는 경우가 많아 소속사 가이드와 저작권 규정을 확인해야 한다. 멤버의 참여 영상을 사생활처럼 소비하거나 과장하면 팬 사이 논란이 생길 수 있다. 음악방송 성적과 챌린지 반응은 시점마다 달라지므로 발매 초기 기록으로만 쓰는 것이 좋다.',
  usage_examples = '[{"situation":"아이돌 댄스 챌린지 이야기가 나왔을 때","text":"DASH 챌린지 기억나? 발매하고 얼마 안 돼서 음방 1위 줄줄이 찍었지."},{"situation":"챌린지 커버 영상에 댓글을 남길 때","text":"이 커버 보니까 DASH 챌린지 생각나네. 다음엔 누가 같이 추려나?"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'p9n65wbu'
  and slug = 'DASH-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

