-- H.O.T. 데뷔 신드롬 (ptpx5kfx / H.O.T.-데뷔-신드롬)
update public.memes set
  description = 'H.O.T.는 SM엔터테인먼트가 최초로 기획하고 데뷔시킨 5인조 보이그룹으로, 1996년 9월 7일 MBC ''토요일 토요일은 즐거워''를 통해 데뷔했다. ''High-five Of Teenagers''라는 이름처럼 10대를 겨냥한 노래와 춤으로 인기를 얻었고, 1집부터 4집까지 모두 밀리언셀러를 기록했으며 가요시상식 대상을 12회 수상했다고 전해진다. 1997년 데뷔한 젝스키스와의 경쟁 구도 속에서 두 그룹 팬덤이 함께 커졌고, OSEN은 대형 콘서트 현장에서 양쪽 팬덤이 신경전을 벌일 만큼 경쟁이 치열했다고 전했다. 두 그룹을 상징하는 하얀색과 노란색 우비, 야광봉도 1990년대 말 팬 응원의 모습으로 소개된다.',
  origin = 'SM엔터테인먼트가 최초로 기획하고 데뷔시킨 그룹으로, 1996년 9월 7일 MBC ''토요일 토요일은 즐거워''를 통해 데뷔했다. 타이틀곡 ''전사의 후예''와 후속곡 ''Candy''가 인기를 끌었고, OSEN은 H.O.T.가 그해 가요시상식 신인상을 휩쓸었다고 전했다.',
  usage_note = '1세대 아이돌 팬덤 문화와 기획형 아이돌 산업의 출발점을 설명할 때 인용하면 적절하다. 젝스키스와의 라이벌 구도를 함께 언급하면 1990년대 후반 가요계의 분위기를 전달하기 쉽다.',
  caution = '팬덤 규모 수치는 집계 기준에 따라 달라 보도마다 차이가 있다. 유료 회원 약 22만 명, 비공식 팬덤까지 합치면 약 70만 명이라는 식으로 기준을 밝혀 인용하는 것이 좋다. 팬덤 일화를 다룰 때는 당시 상황이라는 점을 함께 적어야 한다.',
  usage_examples = '[{"situation":"카톡","text":"1세대 팬덤 문화 시작이 H.O.T. 데뷔였지"},{"situation":"SNS 댓글","text":"클럽 H.O.T. 응원 문화 그때가 시작이었지"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ptpx5kfx'
  and slug = 'H.O.T.-데뷔-신드롬'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

