-- 병뚜껑 챌린지 (rhp52s5u / 병뚜껑-챌린지)
update public.memes set
  description = '병뚜껑 챌린지는 병을 고정한 채 발차기로 느슨하게 닫힌 병뚜껑만 돌려 여는 도전이다. 병을 움직이지 않고 한 번의 킥으로 뚜껑만 돌려 열어야 해서 발차기 실력을 겨루는 놀이처럼 번졌고, 대부분 슬로모션으로 촬영해 #BottleCapChallenge 해시태그와 함께 올렸다. CBS 뉴스는 2019년 7월 3일 보도에서 이 챌린지가 격투기계에서 먼저 돌았고, 디자이너 에롤슨 휴가 시작해 UFC 페더급 챔피언 맥스 할러웨이가 대중문화로 넘겼다고 전했다. 배우 제이슨 스타뎀과 가수 존 메이어도 영상을 올렸다. 국내에서는 2019년 7월 27일 방송 예정이던 JTBC ''아는 형님''에서 출연진이 이 챌린지에 도전했다고 소개됐다.',
  origin = 'CBS 뉴스는 2019년 7월 3일 보도에서 디자이너 에롤슨 휴(Errolson Hugh)가 시작했고 격투기 선수 맥스 할러웨이가 주류로 넓혔다고 전했다. 할러웨이는 2019년 6월 28일 존 메이어를 지목했고, 메이어는 6월 29일 제이슨 스타뎀을 지목했으며 스타뎀이 7월 초 영상을 올리며 확산됐다. 국내에서는 twig24가 2019년 7월 27일 방송 예정이던 ''아는 형님''의 도전을 소개했다.',
  usage_note = '2019년 SNS 챌린지 유행을 설명할 때 대표 사례로 인용한다. 누구나 간단한 동작을 따라 하던 시기의 밈 문화를 언급하는 데 적합하다.',
  caution = '발차기로 병을 맞히는 동작이므로 실제로 따라 하면 다칠 수 있고, 유리병이 깨질 위험도 있다. 유명인 영상을 캡처해 인용할 때는 원게시자를 밝히고 저작권을 확인한다.',
  usage_examples = '[{"situation":"카톡","text":"이거 병뚜껑 챌린지 생각나서 웃었다"},{"situation":"SNS 댓글","text":"2019년 병뚜껑 챌린지 다시 보고 싶다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'rhp52s5u'
  and slug = '병뚜껑-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

