-- 조규성 신드롬 (tyt94hyh / 조규성-신드롬)
update public.memes set
  description = '조규성은 2022 카타르 월드컵 우루과이전에 후반 교체로 투입되어 월드컵 데뷔전을 치렀다. 경기가 끝난 뒤 훈훈한 외모가 해외 팬들 사이에서 화제가 되며 SNS 팔로워가 단기간에 크게 늘었다. 뉴시스는 경기 전 4만여 명이던 팔로워가 하루 만에 35만 명을 넘었다고 전했고, 노컷뉴스는 월드컵 기간 150만 명을 넘었다고 보도했다. YTN은 2022년 12월 7일 방송에서 팔로워가 3만 명에서 260만 명 이상으로 늘었다고 전했다. 집계 시점과 기준이 달라 수치는 보도마다 차이가 있다. 노컷뉴스는 이 인기를 ''만찢남'' 열풍이라고 표현했고, 조규성이 가나전에서 한국 선수 최초로 월드컵 한 경기 멀티골을 기록했다고 전했다.',
  origin = '2022년 11월 24일(현지 시간) 카타르 월드컵 H조 1차전 우루과이전에서 후반 29분 교체 투입된 뒤 외모가 화제가 됐다. 뉴시스는 경기 전 4만여 명이던 SNS 팔로워가 25일 오후 3시 기준 35만 명을 넘었다고 전했다. YTN은 12월 7일 팔로워가 3만 명에서 260만 명 이상으로 늘었다고 보도했다.',
  usage_note = '월드컵 기간 화제를 모은 선수의 인기 급상승을 설명할 때 인용한다. 축구 이야기 자리에서 외모나 SNS 반응을 가볍게 언급하는 용도로 쓸 수 있다.',
  caution = '외모를 대상으로 한 화제이므로 신체나 외형을 조롱하는 식으로 쓰면 선수에게 상처가 될 수 있다. 팔로워 증가 수치는 집계 시점마다 다르므로 특정 숫자를 단정하지 않는다. 경기 장면이나 중계 화면을 인용할 때는 방송사 저작권에 주의한다.',
  usage_examples = '[{"situation":"카톡","text":"월드컵 때 조규성 신드롬 기억나지"},{"situation":"SNS 댓글","text":"교체로 들어와서 이 정도 화제면 대단하다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'tyt94hyh'
  and slug = '조규성-신드롬'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

