-- 정국 세븐 챌린지 (tzq32hak / 정국-세븐-챌린지)
update public.memes set
  description = '정국의 솔로곡 ''Seven(feat. Latto)''의 안무를 따라 추는 댄스 챌린지다. 팬들이 전 세계에서 커버 영상을 올리는 #SevenDaysAWeek 챌린지로 확산됐고, 그 과정에서 정국이 위버스에서 공유한 커버 영상이 개인 틱톡 계정을 드러내는 일이 화제가 됐다. 한 매체는 이 계정이 챌린지 참가자 선정에도 쓰였을 것으로 추정했다. 정국이 좋아요를 누른 영상 목록에는 ''Seven'' 커버가 여럿 포함됐다고 정리됐다. 정국은 위버스에서 이 계정이 모니터링용이라고 밝혔다고 보도됐다.',
  origin = '2023년 8월 초 보도된 사건이다. 정국이 2023년 8월 1일 위버스에서 BOYNEXTDOOR 멤버들의 ''Seven'' 커버 영상을 공유하면서 비공개 틱톡 계정이 함께 드러났다고 전해졌다. 정국이 좋아요를 누른 영상 가운데 ENHYPEN의 #SevenDaysAWeek 챌린지 영상이 포함된 것으로 보도됐다. ''Seven''은 2023년 7월 발매된 정국의 솔로 데뷔 싱글이다.',
  usage_note = '정국의 솔로 활동이나 ''Seven'' 챌린지 열풍을 회고할 때 인용한다. 팬 참여형 챌린지가 SNS에서 확산되던 방식을 설명하는 사례로도 쓸 수 있다.',
  caution = '정국의 개인 계정 노출은 본인이 당황했다고 전해진 사안이므로 사생활을 추측하거나 계정을 찾아내는 식으로 언급하지 않는다. 보도가 영문 연예 매체 중심이라 국내 사실 확인이 추가로 필요하다. 안무 영상을 인용할 때는 게시자의 저작권을 확인한다.',
  usage_examples = '[{"situation":"카톡","text":"Seven 챌린지 그때 얘기 아직도 나오더라"},{"situation":"SNS 댓글","text":"SevenDaysAWeek 챌린지 영상 보니 다시 춤추고 싶다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'tzq32hak'
  and slug = '정국-세븐-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

