-- 바디프로필 열풍 (uvkw33ur / 바디프로필-열풍)
update public.memes set
  description = '바디프로필은 고강도 운동과 식이요법으로 몸을 만든 뒤 전문 스튜디오에서 모델처럼 사진을 촬영하는 것을 가리킨다. 예전에는 운동선수나 연예인 등의 전유물로 여겨졌으나, 조선일보는 2020년 8월 보도에서 20~40대 일반인들이 젊을 때의 몸을 사진으로 남기고 SNS에 올리려는 버킷리스트가 됐다고 전했다. 당시 인스타그램의 ''#바디프로필'' 해시태그 게시물은 95만 건을 넘었다. 사이언스타임즈 칼럼은 2021년 8월 촬영을 위해 짧게는 2개월, 길게는 6개월 운동해야 하며 바디프로필이 건강과 자기관리의 상징이 됐다고 설명했다. 같은 칼럼은 무리한 체중 감량과 요요현상 같은 부작용도 함께 짚었다.',
  origin = '조선일보는 2020년 8월 6일 보도에서 바디프로필 촬영이 20~40대 일반인의 버킷리스트가 됐다고 전했다. 사이언스타임즈 칼럼은 2021년 8월 운동선수나 연예인의 수단이던 촬영이 일반인에게도 유행처럼 번졌다고 설명했다. 바디프로필 열풍의 정확한 시작 시점은 조회한 자료에서 확인하지 못했다.',
  usage_note = '자기관리나 다이어트 열풍을 설명할 때 예시로 인용한다. 운동과 촬영이 결합된 SNS 소비 문화를 언급하는 데 적합하다.',
  caution = '체중 감량과 근육 만들기 과정이 무리한 식이나 과도한 운동으로 이어질 수 있다는 점을 함께 다뤄야 한다. 일반인의 신체 사진을 인용하거나 외모를 평가하는 식으로 쓰면 개인에게 상처가 될 수 있다. 촬영 스튜디오의 광고 이미지는 저작권과 초상권을 확인해야 한다.',
  usage_examples = '[{"situation":"카톡","text":"바디프로필 찍는 사람 많던데 나도 해볼까"},{"situation":"SNS 댓글","text":"바디프로필 준비하느라 식단 관리 장난 아니겠다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'uvkw33ur'
  and slug = '바디프로필-열풍'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

