-- Chk Chk Boom 챌린지 (vpkqwfaq / Chk-Chk-Boom-챌린지)
update public.memes set
  description = 'Chk Chk Boom 챌린지는 스트레이 키즈가 2024년 7월 미니앨범 ''ATE''의 타이틀곡 ''Chk Chk Boom'' 발매에 맞춰 유튜브 쇼츠에서 진행한 공식 챌린지다. 팬들은 공식 안무를 따라 하되 자신만의 해석을 더해 ''ChkChkBoom'' 해시태그와 함께 쇼츠를 올렸다. 유튜브 공식 블로그는 쇼츠 화면에서 ''사운드 추가''로 곡을 검색해 바로 녹화하는 절차를 안내했다. 위키백과는 발매 전인 7월 10일 매시업 영상이 먼저 공개된 사실도 기록하고 있다. 같은 문서에 따르면 뮤직비디오에는 라이언 레이놀즈와 휴 잭맨이 데드풀과 울버린 복장으로 출연했고, 이 영상은 스트레이 키즈의 15번째 유튜브 1억 뷰 뮤직비디오가 됐다.',
  origin = '위키백과에 따르면 ''Chk Chk Boom''은 2024년 7월 19일 발매된 ''ATE'' 수록곡이다. 스트레이 키즈는 7월 18일 유튜브 쇼츠와 협업해 댄스 챌린지를 시작하며 곡을 홍보했다.',
  usage_note = '유튜브 공식 챌린지가 음악 프로모션에 쓰인 사례로 인용한다. 아이돌 컴백과 숏폼 플랫폼 마케팅을 함께 설명할 때 적합하다.',
  caution = '공식 안무 영상의 저작권과 음원 사용 조건은 플랫폼 정책과 소속사 가이드를 따라야 한다. 안무를 무단으로 재편집해 상업적으로 쓰면 문제가 될 수 있다. 팬 영상을 인용할 때는 게시자를 밝힌다.',
  usage_examples = '[{"situation":"카톡","text":"Chk Chk Boom 챌린지 쇼츠 올려봤는데 생각보다 재밌다"},{"situation":"SNS 댓글","text":"후렴 안무 따라 추는 챌린지 아직도 올라오네"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'vpkqwfaq'
  and slug = 'Chk-Chk-Boom-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

