-- 러닝크루 열풍 (wckprcwc / 러닝크루-열풍)
update public.memes set
  description = '러닝크루는 SNS를 통해 모여 함께 달리는 달리기 모임을 가리킨다. 매경이코노미는 2025년 9월 보도에서 러닝 인구가 천만 명 시대에 들어섰고 네이버 밴드의 러닝·걷기 모임이 2년 새 46% 늘었다고 전했다. 같은 기사는 크루 단위로 좁은 도보를 뛰어 위험하다는 지적이 나오자 일부 시민이 러닝 크루를 자전거 무법자 ''자라니''보다 무섭다며 ''런라니''라는 신조어를 만들었다고 설명했다. 지데일리 2026년 7월 보도에 인용된 엠브레인 트렌드모니터 조사에서는 러닝 크루에 호감을 느낀다는 응답이 33.9%, 비호감이라는 응답이 44.9%였다. 공공 공간을 점유한다는 불만과 건강·교류 문화라는 평가가 함께 나오고 있다.',
  origin = '매경이코노미는 SNS의 ''런스타그램'' 문화와 코로나19 이후 달리기 붐이 맞물려 확산됐다고 분석했다. 인스타그램 러닝 해시태그 게시물은 2023년 말 약 200만 건이던 것이 2025년 9월 기준 400만 건을 넘었다.',
  usage_note = '운동 트렌드와 추구미 문화를 설명할 때 예시로 인용한다. 달리기 모임이 SNS에서 확산되며 생긴 공공장소 이용 갈등을 언급하는 자리에 쓰기 좋다.',
  caution = '크루 전체를 특정 집단으로 낙인찍는 표현이므로 비난 목적으로 쓰면 특정 모임이나 러너에게 상처가 될 수 있다. 신조어는 공식 용어가 아니므로 출처 없이 단정하지 않는다. 지역 민원이나 규제 논의는 시점에 따라 바뀌므로 보도 날짜를 함께 밝힌다.',
  usage_examples = '[{"situation":"카톡","text":"주말 러닝크루 때문에 도보 막히는 거 진짜 불편하더라"},{"situation":"SNS 댓글","text":"런라니 소리 나올 만큼 크루 단위 질주는 좀 줄였으면"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'wckprcwc'
  and slug = '러닝크루-열풍'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

