-- 1박2일 복불복 (wtcrevxq / 1박2일-복불복)
update public.memes set
  description = '복불복은 운수를 뜻하는 말로, KBS 2TV 예능 ''1박2일''에서 잠자리나 식사를 걸고 벌인 운에 따른 게임 방식을 가리킨다. 이 프로그램은 2007년 8월 5일 첫 방송을 시작했으며, 야외 여행 중 벌이는 복불복 게임이 프로그램을 대표하는 장치로 자리 잡았다. 2013년 경남신문 기사는 복불복이 ''벌칙을 정하는 게임''의 대명사가 됐을 정도라고 전했다. 초기 출연진은 강호동, 이수근, 은지원, 노홍철, 지상렬, 김종민이었으며, 콧김으로 촛불을 끄는 등 자연경관 속 대결 게임이 시청자의 호응을 얻었다는 평가가 있다.',
  origin = 'KBS 2TV 예능 ''1박2일''(2007년 8월 5일 첫 방송)의 복불복 게임에서 비롯된 말이다. 방송 초기 어느 시점에 유행어가 됐는지는 확인된 자료가 없어 정확한 연도는 특정하지 않는다.',
  usage_note = '운에 따라 벌칙이나 보상이 갈리는 상황을 가볍게 말할 때 쓴다. 점심 내기나 역할 분담처럼 가벼운 결정에 붙이면 자연스럽고, 실패 책임을 특정인에게 몰아가는 맥락에서는 쓰지 않는 편이 낫다.',
  caution = '방송에서 출연자가 벌칙을 맡는 장면이 많아, 이를 인용할 때 실제 인물을 조롱하는 식으로 쓰지 않도록 주의해야 한다. 방송 장면 캡처나 클립을 그대로 가져오면 방송사의 저작권 문제가 생길 수 있다.',
  usage_examples = '[{"situation":"카톡","text":"오늘 저녁 메뉴는 복불복으로 정하자"},{"situation":"SNS 댓글","text":"이번 조 편성은 완전 복불복이네, 걸린 사람 고생 각"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'wtcrevxq'
  and slug = '1박2일-복불복'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

