-- 밥은 먹고 다니냐 (xtm69k7y / 밥은-먹고-다니냐)
update public.memes set
  description = '2003년 개봉한 봉준호 감독의 영화 ''살인의 추억''에서 송강호가 연기한 박두만 형사의 대사다. 위키백과는 이 말을 송강호가 영화 안에서 했던 애드리브로 소개하며, 개봉 이후에도 큰 화제가 되어 영화를 대표하는 유행어 중 하나가 되었다고 적는다. 송강호는 영화 속 범인을 넘어 실제 화성 연쇄살인 사건의 범인에게 하는 말이라고 설명했고, 봉준호 감독은 형사와 범인이 눈을 마주치게 하려는 의도였다고 밝혔다. 영화는 2003년 4월 25일 개봉했으며 화성 연쇄살인 사건이라는 실화를 바탕으로 했다. 한국영상자료원이 선정한 한국 영화 명대사 100선에도 올랐다.',
  origin = '2003년 4월 25일 개봉한 영화 ''살인의 추억''의 대사다. 위키백과는 송강호가 영화 안에서 한 애드리브로 소개한다. 송강호는 씨네21 인터뷰에서 봉준호 감독이 터널 앞 장면을 찍기 사흘 전부터 그 장면에 무슨 말이 있을 것 같다고 언질을 줬고, 사흘 동안 어떤 말을 할지 고민했다고 말했다.',
  usage_note = '안부를 씁쓸하거나 의미심장하게 물을 때 패러디로 쓴다. 오랜만에 만난 사람에게 가볍게 건네는 인사로도 쓸 수 있지만, 영화 장면을 떠올리게 하는 말이라 상대가 농담으로 받아들일 수 있는 관계에서 쓰는 편이 자연스럽다.',
  caution = '영화가 실제 연쇄살인 사건을 모티브로 했기 때문에 피해자나 실제 사건을 가볍게 다루는 맥락에서는 쓰지 않는 것이 좋다. 영화 장면 클립을 가져올 때는 배급사의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"바빠 보이는 친구에게","text":"바쁜 것 같던데 밥은 먹고 다니냐?"},{"situation":"영화 이야기","text":"송강호가 밥은 먹고 다니냐 하는 장면 진짜 소름이었어"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'xtm69k7y'
  and slug = '밥은-먹고-다니냐'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

