-- 소녀시대 Forever 1 15주년 (xxaw8946 / 소녀시대-Forever-1-15주년)
update public.memes set
  description = '소녀시대가 데뷔 15주년을 맞아 2022년 8월 발표한 정규 7집 ''FOREVER 1''(포에버 원)과 타이틀곡을 가리킨다. 2017년 정규 6집 ''홀리데이 나이트'' 이후 5년 만에 8명 완전체로 내놓은 앨범이며 총 10곡이 수록됐다. 2007년 8월 5일 ''다시 만난 세계''로 데뷔한 그룹은 데뷔 15주년인 2022년 8월 5일 서울 코엑스 인터컨티넨탈에서 발매 기자회견을 열었다. 타이틀곡은 데뷔곡부터 함께한 작곡가 켄지가 작곡과 전체 프로듀싱을 맡았고, 멤버들은 앨범에 자신들의 의견을 많이 담았다고 밝혔다.',
  origin = '2022년 8월 5일 서울 강남구에서 정규 7집 ''FOREVER 1'' 발매 기자회견이 열렸다. 타이틀곡 ''Forever 1''은 멤버 수영이 작곡가 켄지에게 데뷔곡 ''다시 만난 세계''를 떠올리게 하는 부분이 있었으면 좋겠다고 요청해 만들어진 곡으로 소개됐다. 이날은 소녀시대의 데뷔 15주년 기념일이었다.',
  usage_note = '오랜 기간 활동한 아이돌 그룹이 완전체로 재결합하는 이야기나 데뷔 기념일 회고에 인용하기 좋다. 앨범명은 ''포에버 원''(FOREVER 1), 타이틀곡 제목은 ''Forever 1''로 구분해 쓰면 혼동을 줄일 수 있다.',
  caution = '앨범과 곡에 대한 평가는 청자와 매체에 따라 갈리므로 특정 평가를 사실처럼 옮기지 않도록 주의해야 한다. 가사나 뮤직비디오 장면을 옮길 때는 소속사와 제작사의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"음악 커뮤니티","text":"소녀시대 포에버 원 나왔다는데 15주년에 완전체라니 감격이다"},{"situation":"카톡","text":"8월 되니까 소녀시대 15주년 생각난다, 포에버 원 들어봤어?"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'xxaw8946'
  and slug = '소녀시대-Forever-1-15주년'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

