-- 배달의 무도 (yv2fk2un / 배달의-무도)
update public.memes set
  description = '2015년 MBC ''무한도전''이 광복 70주년을 맞아 내놓은 특집으로, 해외에 거주하는 한국인들에게 따뜻한 밥상을 배달하는 내용이다. 박명수는 칠레 푼타아레나스에서 사연의 주인공을 만난 뒤 남극 세종기지 대원들에게 가족의 정성을 전했고, 하하와 유재석은 일본 오사카의 우토로 마을과 하시마섬을 찾았다. 정형돈과 황광희는 유럽으로 떠났다. 앞선 방송에서는 타국으로 입양된 사연의 주인공과 그 가족의 모습이 소개됐으며, 세 번째 이야기는 무한도전 444회로 방송됐다.',
  origin = '광복 70년 특집으로 편성된 ''배달의 무도''의 세 번째 이야기가 2015년 9월 5일 방송된 무한도전 444회에서 전파를 탔다. 이 특집은 광복 70주년을 맞아 해외에 거주 중인 한국인들에게 따뜻한 밥상을 배달하는 내용으로 소개됐다.',
  usage_note = '예능이 역사 문제를 다루거나 공익 메시지를 담은 사례를 이야기할 때 인용한다. 배달이나 여행 예능이라는 소재만 말할 때는 맥락이 맞지 않으므로 방송 제목과 연도를 함께 적는 것이 좋다.',
  caution = '역사 문제를 다룬 특집이므로 장소와 사건을 가볍게 농담거리로 소비하지 않도록 한다. 방송 장면을 인용할 때는 MBC의 저작권을 존중해 짧은 설명으로 대신하는 편이 안전하다.',
  usage_examples = '[{"situation":"예능 이야기","text":"무도 배달의 무도 편은 광복 70주년 특집이라 의미가 남달랐어"},{"situation":"역사 얘기","text":"배달의 무도에서 하시마섬 편 보고 역사 교육이 이렇게도 되는구나 싶었어"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'yv2fk2un'
  and slug = '배달의-무도'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

