-- 두바이초콜릿 신드롬 (z6zarg9q / 두바이초콜릿-신드롬)
update public.memes set
  description = '두바이 초콜릿은 아랍에미리트 초콜릿 브랜드 픽스(Fix)가 2021년 출시한 제품으로, 얇은 면 카다이프와 피스타치오 크림을 초콜릿 안에 채운 것이 특징이다. 2023년 12월 아랍에미리트의 음식 인플루언서가 SNS에 이 초콜릿을 먹는 영상을 올리며 유명해졌고, 틱톡을 중심으로 퍼진 것으로 보도됐다. 2024년 7월 한국에서도 열풍이 불어 CU가 ''두바이 스타일 초콜릿''을 내놓았고, GS25와 세븐일레븐, 이마트24도 관련 상품 출시를 예고했다. 2025년 4월에는 수요 급증으로 피스타치오 가격이 국제적으로 오르고 공급 부족이 나타났다는 분석이 보도됐다.',
  origin = '2023년 12월 아랍에미리트의 음식 인플루언서가 SNS에 이 초콜릿을 먹는 영상을 올린 것이 계기다. 찐득한 크림과 카다이프가 바삭하게 씹히는 소리가 담긴 이 영상은 2024년 7월 4일 보도 기준 조회수가 6천만 회를 넘었다. 같은 보도에 따르면 CU는 2024년 7월 6일부터 ''두바이 스타일 초콜릿'' 판매를 시작했다.',
  usage_note = '유행 디저트나 해외에서 들어온 유행 상품을 이야기할 때 쓴다. 제품이 품절되거나 재구매가 어렵다는 상황을 가볍게 말하는 데도 적합하다. 2025년 이후 유행한 다른 디저트와 섞어 쓰면 시점이 흐려질 수 있으니 구분해서 쓰는 편이 좋다.',
  caution = '유사품과 원조 제품을 혼동하지 않도록 주의해야 한다. 피스타치오 가격 급등은 수급 요인이 얽힌 문제라 두바이 초콜릿 하나를 단정적인 원인으로 설명하지 않는 것이 좋다. 틱톡 영상 클립을 인용할 때는 게시자의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"디저트 얘기","text":"두바이 초콜릿 편의점 또 품절이래, 이번 유행도 오래 가네"},{"situation":"SNS 댓글","text":"피스타치오 가격 올랐다는 기사 보니 두바이 초콜릿 영향도 있는 듯"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'z6zarg9q'
  and slug = '두바이초콜릿-신드롬'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

