-- 소녀시대 다시 만난 세계 (2ka7y6ya / 소녀시대-다시-만난-세계)
update public.memes set
  description = '소녀시대가 2007년 8월 5일 발표한 데뷔곡으로, 작사는 김정배, 작곡은 켄지가 맡았다. 2016년 이화여대 학생들이 농성 중 경찰과 대치하던 상황에서 이 곡을 불렀고, 투쟁가 대신 대중가요가 울려 퍼진 장면이 사회적으로 주목받았다. 뉴시스는 이 곡을 ''젊은 세대의 아침이슬''이라 부르는 이도 있다고 전했다. 2020년 태국 반정부 시위에서는 시위대가 이 곡에 맞춰 춤추고 노래하는 영상이 SNS에서 인기를 끌었고, 2024년 12월 서울 여의도 집회에서도 다시 울려 퍼졌다. 멤버 수영은 데뷔 당시 멋모르고 부른 곡이 시간이 지나며 여러 의미로 해석된다고 밝혔다.',
  origin = '2007년 8월 5일 소녀시대가 이 곡으로 데뷔했다. 2016년 이화여대 학생들이 부정입학 의혹과 평생교육 단과대학 설립에 반대하며 농성하다 경찰과 대치하던 상황에서 불렀다는 보도가 있다. 이후 2020년 태국 시위대와 2024년 여의도 집회 참가자들이 함께 부른 것으로 소개됐다.',
  usage_note = '떼창이나 응원곡이 시위와 집회에서 불리는 현상을 설명할 때 인용할 수 있다. 한 평론가가 한국 아이돌 팝 최고의 데뷔곡이라고 평가한 곡이어서 2세대 걸그룹의 대표 데뷔곡을 이야기할 때 언급하기에도 적합하다.',
  caution = '정치적 집회나 시위와 엮이는 곡이라 특정 정치 성향을 드러내는 맥락으로 쓰면 논쟁이 될 수 있다. 음원이나 뮤직비디오를 옮길 때는 권리자의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"음악 얘기","text":"다시 만난 세계 들으면 2007년 데뷔 시절이 떠오른다"},{"situation":"커뮤니티 댓글","text":"여의도 집회에서 다시 만난 세계 떼창 나왔다는 얘기 듣고 놀랐음"}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '2ka7y6ya'
  and slug = '소녀시대-다시-만난-세계'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

