-- 무한도전 토토가 (46n84j7c / 무한도전-토토가)
update public.memes set
  description = '''토요일 토요일은 가수다''(토토가)는 MBC ''무한도전''이 2014년 12월 27일 방송한 연말 특집이다. 터보, 김현정, 쿨, S.E.S, 조성모, 소찬휘, 이정현, 지누션, 엄정화, 김건모 등 1990년대 가수들이 출연했고, 박명수와 정준하가 기획해 사회를 맡았다. 첫 무대는 18년 만에 완전체로 돌아온 터보가 장식했고, S.E.S는 출산 준비로 빠진 유진 대신 소녀시대 서현이 함께했다. 닐슨코리아 전국 기준 시청률은 19.8%로 그해 ''무한도전'' 최고 시청률이었고 평소 10~13%를 크게 웃돌았다. 1990년대에 이 가수들의 팬이었던 70~80년대생이 특히 열광했다고 보도됐다.',
  origin = 'MBC ''무한도전'' 연말 특집으로 2014년 12월 27일 방송됐다. 12월 20일에는 준비 과정을 담은 방송(15.3%)이 먼저 나갔고, 남은 무대는 2015년 1월 3일에 이어졌다. 헤럴드경제 미주판은 2015년 1월 5일 기사에서 방송 이후 반응이 뜨겁게 이어지고 있으며 제작진도 예상을 뛰어넘는 반응에 놀라는 눈치라고 전했다.',
  usage_note = '1990년대 가수들이 다시 모인 무대나 복고 열풍을 이야기할 때 인용한다. 세대공감 소재로 과거 가요를 떠올리는 대화에서 자주 쓰인다. 특정 가수의 무대를 평가할 때는 방송 당시의 반응을 기준으로 말하는 것이 무난하다.',
  caution = '시청률은 조사기관과 지역에 따라 닐슨코리아 전국 19.8%, TNmS 수도권 24.8%처럼 다르게 보도되었으므로 한 숫자로 단정하지 않는 것이 좋다. 방송 영상과 캡처는 MBC와 소속사의 저작물이라 무단 게시를 피해야 한다. 출연 가수 개인을 조롱하는 식의 2차 가공은 명예훼손 소지가 있어 피해야 한다.',
  usage_examples = '[{"situation":"복고 음악 얘기가 나왔을 때","text":"토토가 때 터보 무대 다시 보면 옛날 생각 난다ㅋㅋ"},{"situation":"댓글로 추억을 공유할 때","text":"이 노래 토토가에서 듣고 다시 빠졌었음. 복고 열풍 제대로였지."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '46n84j7c'
  and slug = '무한도전-토토가'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

