-- 히끄(제주 고양이) (4c7ee8a9 / 히끄(제주-고양이))
update public.memes set
  description = '제주 오조리를 누비던 길고양이였던 히끄는 게스트하우스 스태프로 일하던 집사를 우연히 만나 함께 살게 되었다. 희끄무레한 털 색에서 이름이 붙었고, 절친으로는 꺼뭇꺼뭇한 꺼므가 있다. 마리끌레르 코리아는 2018년 1월호에서 히끄를 ''냥스타그램 슈퍼스타''로 소개하며 목욕을 시켜도, 비행기를 타도 잠자코 있는 적응력을 꼽았다. 일상을 담은 에세이 『히끄네 집』은 2017년 10월 야옹서가에서 출간됐고 증쇄 중이라고 전해졌다. 인사이트는 2018년 10월 기사에서 이 책을 고양이 책 8권 중 첫 번째로 소개하며 히끄의 사진이 가득 담겼다고 설명했다.',
  origin = '게스트하우스 스태프였던 집사를 만나 함께 살게 된 경위는 마리끌레르 코리아 2018년 1월호에 소개됐다. 집사가 게스트하우스를 열기 전부터 함께 지냈다고 한다. 에세이 『히끄네 집』은 2017년 10월 야옹서가에서 출간됐다.',
  usage_note = 'SNS에서 인기를 끈 반려묘나 길고양이 입양 사례를 소개할 때 인용한다. 유기묘가 가족을 만나 사랑받는 이야기를 말할 때 쓰기 좋다. 고양이 에세이나 사진집을 추천하는 맥락에서도 언급된다.',
  caution = '고양이 사진과 일상을 담은 게시물을 가져올 때는 작가와 촬영자의 저작권을 존중해야 한다. 기사 속 사진에는 촬영자 크레딧이 붙어 있어 무단 이미지 사용을 피해야 한다. 반려인과 고양이의 사생활이나 생활 장소를 과도하게 추적하거나 공개하는 것은 사생활 침해 소지가 있다.',
  usage_examples = '[{"situation":"고양이 입양 이야기가 나왔을 때","text":"길고양이가 집사를 만나 행복해진 히끄 이야기 알아? 훈훈하더라."},{"situation":"고양이 책을 추천할 때","text":"랜선 집사라면 히끄네 집 한 번 읽어봐. 고양이 일상이 잘 담겨 있어."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '4c7ee8a9'
  and slug = '히끄(제주-고양이)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

