-- 라떼 메이크업 (4j37qxtc / 라떼-메이크업)
update public.memes set
  description = '라떼 메이크업은 진한 에스프레소에 우유가 녹아든 라테처럼 부드럽고 따뜻한 브라운 계열 색감으로 완성하는 메이크업이다. 얼루어 코리아는 부드럽고 따뜻한 커피를 닮았다고 해 이런 이름이 붙었다고 설명한다. Who What Wear는 브론즈와 브라운 톤으로 햇볕에 그을린 듯한 부드러운 인상을 만드는 룩이며 제품을 과하게 쓰지 않는다고 소개했다. 2023년 7월 헤일리 비버가 틱톡에서 브론저를 많이 쓰고 베이스 메이크업은 최소화한 자신의 해석을 공유했고, 보그 코리아와 얼루어 코리아 같은 국내 뷰티 매체도 이 메이크업을 다뤘다.',
  origin = '2023년 7월 헤일리 비버가 틱톡에 올린 시연 영상이 화제가 됐고, 같은 달 Who What Wear가 이 룩을 틱톡에서 힘을 얻는 새 뷰티 트렌드로 소개했다. 2023년 7월 27일 보그 코리아가 ''라테 메이크업''을, 8월 4일에는 얼루어 코리아가 ''라떼 메이크업 tip''을 다뤘다.',
  usage_note = '브라운 계열 색감으로 부드럽고 따뜻한 인상을 만드는 메이크업을 설명할 때 쓴다. 커피 색감을 연상시키는 이름이라 화장품 추천이나 메이크업 후기에서 쓰인다. 뷰티 기사나 콘텐츠에서 이 룩을 소개하는 표현으로 활용하면 된다.',
  caution = '특정 인플루언서의 얼굴과 영상을 무단으로 가져와 광고처럼 쓰면 초상권과 광고 규제 문제가 생길 수 있다. 2023년에 화제가 된 룩이므로 시간이 지난 뒤에도 같은 인기를 누린다고 단정하면 부정확하다. 피부톤에 맞지 않는 색을 쓰면 탁하게 보일 수 있어 과장된 효과를 약속하는 표현은 피하는 것이 좋다.',
  usage_examples = '[{"situation":"메이크업 얘기가 나왔을 때","text":"2023년에 화제가 된 라떼 메이크업 아세요? 브론저 위주라 따뜻해 보여요."},{"situation":"친구에게 추천할 때","text":"라떼 메이크업은 브론저를 많이 쓰고 베이스는 얇게 바르는 게 포인트래. 한번 해봐."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '4j37qxtc'
  and slug = '라떼-메이크업'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

