-- Armageddon 챌린지 (5pnbhqdj / Armageddon-챌린지)
update public.memes set
  description = '에스파의 곡 ''Armageddon(아마겟돈)''에 맞춘 댄스 챌린지다. 노컷뉴스에 따르면 에스파와 뉴진스는 2024년 6월 8일 에스파의 신곡 ''아마겟돈''과 뉴진스의 신곡 ''하우 스위트'' 댄스 챌린지 영상을 서로 틱톡과 쇼츠에 공개했다. ''아마겟돈''은 에스파 카리나와 지젤, 뉴진스 민지와 해린이 췄고, 6월 9일 오후 5시 기준 쇼츠 조회수는 120만 회였다. 2024년 6월 30일 서울 잠실 실내체육관에서 열린 에스파의 두 번째 단독 콘서트 ''SYNK : PARALLEL LINE''에서는 ''Armageddon'' 무대가 끝난 뒤 팬들에 이어 청하와 혜리의 댄스 챌린지가 예고 없이 시작돼 현장에 웃음을 자아냈다.',
  origin = '2024년 6월 8일 에스파와 뉴진스가 서로의 신곡 ''아마겟돈''과 ''하우 스위트'' 댄스 챌린지 영상을 틱톡과 쇼츠에 공개하면서 온라인에서 알려졌다. 노컷뉴스는 6월 9일 오후 5시 기준 ''아마겟돈'' 쇼츠가 조회수 120만 회, 좋아요 16만 회라고 전했다. 2024년 6월 30일 에스파 콘서트에서도 ''Armageddon'' 무대 뒤 댄스 챌린지 코너가 이어졌다.',
  usage_note = '신곡 댄스 챌린지가 온라인에서 먼저 공개된 뒤 콘서트 현장의 팬 참여 코너로 이어진 사례를 설명할 때 쓴다. 다른 그룹과 서로의 곡 챌린지를 교차 공개하는 K팝 홍보 방식을 이야기할 때도 적합하다. 특정 영상을 가리키기보다 ''Armageddon 챌린지''라는 현상으로 언급하는 것이 정확하다.',
  caution = '공연장에서 촬영한 영상을 온라인에 올릴 때는 공연 촬영·공유 규정과 출연자의 초상권을 확인해야 한다. 소속사가 공개한 공식 챌린지 영상과 현장 팬 영상은 출처를 구분해 적어야 하며, 관객의 얼굴이나 신원이 드러나는 장면은 공유하지 않는 편이 좋다.',
  usage_examples = '[{"situation":"콘서트 후기 댓글","text":"잠실 공연에서 아마겟돈 무대 뒤에 댄스 챌린지가 갑자기 시작됐고 청하랑 혜리도 췄다던데 현장 분위기가 궁금하다."},{"situation":"댄스 커버 영상 설명란","text":"에스파 아마겟돈 챌린지 따라 춰봤어요. 팬들끼리 같이 추면 더 신나는 것 같아요."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '5pnbhqdj'
  and slug = 'Armageddon-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

