-- 큐피드 챌린지 (6dqfb248 / 큐피드-챌린지)
update public.memes set
  description = '걸그룹 피프티 피프티(FIFTY FIFTY)가 2023년 2월 24일 발매한 곡 ''Cupid(큐피드)''를 바탕으로 한 틱톡 댄스 챌린지다. 레이디경향은 소속사의 대형 프로모션 없이 틱톡 입소문으로 곡이 알려졌다고 전했다. 쿠키뉴스는 많은 틱톡 이용자가 공유한 스피드업 리믹스 영상으로 노래가 입소문을 탔다고 전했고, 매일신문은 스피드업 숏폼에 한 사용자가 큐피드를 배경음악으로 넣어 올리면서 글로벌 댄스 챌린지가 시작됐다고 소개했다. 가사 ''I gave a second chance to Cupid''에 맞춰 손으로 하트를 그린 뒤 화살을 날리는 안무가 포인트다. 곡은 2023년 3월 말 중소기획사 그룹으로는 처음으로 빌보드 핫 100에 100위로 진입했다.',
  origin = '2023년 2월 24일 발매된 피프티 피프티의 곡 ''Cupid''가 틱톡의 스피드업 버전 확산으로 챌린지가 된 사례다. 레이디경향은 틱톡 이용자가 만든 스피드업 버전이 영상 260만 개 이상에 쓰였고 해시태그 #cupidchallenge 조회수가 약 1억 800만 회라고 보도했다. 쿠키뉴스는 2023년 3월 28일 기준 틱톡의 큐피드 관련 영상이 19만여 개라고 전해, 집계 시점에 따라 수치가 다르다.',
  usage_note = 'K팝 숏폼 챌린지 사례나 스피드업 리믹스가 곡 흥행에 미친 영향을 설명할 때 쓴다. 손하트와 화살 동작처럼 가사와 안무가 결합된 챌린지를 예로 들 때 적합하다. 게시물 수 같은 집계 수치는 보도 시점마다 달라 현상 중심으로 쓰는 편이 안전하다.',
  caution = '2023년 4월 튀르키예 가수가 2017년 자신의 곡과 큐피드 도입부 멜로디가 유사하다고 지적한 일이 보도됐다. 위키트리가 자문한 전문가는 표절로 따질 정도는 아닐 것이라고 했고, 소속사는 원작자 확인에 나섰다고 밝혔다. 챌린지 영상에 쓰인 음원과 안무 클립에는 원저작권자의 권리가 걸려 있으므로 재사용할 때 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"댄스 챌린지 얘기","text":"스피드업 리믹스가 틱톡에서 퍼지면서 큐피드 챌린지가 글로벌 댄스 챌린지로 번졌대. 손하트에 화살 날리는 동작이 포인트래."},{"situation":"숏폼 음원 흥행 글 댓글","text":"스피드업 버전이 틱톡에서 먼저 퍼지고 이후 빌보드 차트에 오른 사례 같아요. 큐피드가 딱 그런 경우죠."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '6dqfb248'
  and slug = '큐피드-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

