-- 원더걸스 텔미 (6jh86zgk / 원더걸스-텔미)
update public.memes set
  description = '원더걸스의 곡 ''Tell Me(텔미)''의 춤을 따라 추는 UCC 열풍을 가리킨다. 박진영이 작사, 작곡과 안무를 맡은 곡으로, 2007년 가을 인터넷에는 학생, 주부, 군대, 외국인 버전과 북한 어린이 율동 화면에 음악만 입힌 영상까지 쏟아졌다. 스포츠경향은 2007년 11월 26일 보도에서 남고생과 선생님, 교통경찰, 군인 버전은 물론 디스코춤에 변형을 가미한 에어로빅, 살사, 발레 버전과 제주 방언, 수화 버전까지 나왔다고 전했다. 같은 기사는 이 열풍을 네티즌이 문화의 소비자이자 생산자인 프로슈머로 제 몫을 한 결과로 설명했다. 주간경향에 따르면 곡은 쥬크온 차트에서 3주 연속 1위를 지켰다.',
  origin = '원더걸스 ''Tell Me''는 2007년 가을 큰 인기를 얻었다. 주간경향은 2007년 11월 13일 기사에서 학생, 주부, 군대, 외국인 버전의 UCC 동영상이 확대 재생산되고 있으며 10월 28일 지상파 가요 프로그램에서 1위를 차지했다고 전했다. 스포츠경향은 2007년 11월 23일과 26일 보도에서 군인과 경찰까지 가세한 UCC 돌풍과 전국적인 텔미춤 열기를 다뤘다.',
  usage_note = '2000년대 후반 UCC 댄스 문화나 누구나 따라 추는 쉬운 안무의 힘을 설명할 때 예로 든다. 아이돌 곡이 일반 대중의 패러디 콘텐츠로 번지는 과정을 이야기할 때 쓰기 좋다. 특정 버전 영상을 가리키기보다 ''텔미 춤 열풍''이라는 현상으로 언급하는 것이 정확하다.',
  caution = '당시 UCC에는 학생, 교사, 교통경찰, 군인 등 일반인이 등장하는 영상이 많았다. 이런 영상을 재사용하거나 특정 개인을 조롱하는 방식으로 소개하면 초상권과 명예훼손 문제가 생길 수 있다. 원곡 음원과 뮤직비디오 클립을 쓸 때는 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"레트로 댄스 얘기","text":"2007년 텔미 춤 UCC 열풍 기억나? 그때는 군인이나 선생님도 텔미 춤을 췄대ㅋㅋ"},{"situation":"댓글","text":"원더걸스 텔미 춤 따라 추던 시절이 제일 재밌었던 것 같아요. 누구나 쉽게 따라 할 수 있는 안무였죠."}]'::jsonb,
  content_reviewed_at = '2026-11-21T12:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '6jh86zgk'
  and slug = '원더걸스-텔미'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

